// Package receipts is a public ledger of sealed predictions.
//
// You seal a call today by publishing only a SHA-256 commitment of it,
// plus a public topic and a date by which you promise to reveal it.
// Later you reveal the exact text and salt; the realm re-hashes them and
// stamps the call as verified, with the block height and time it was
// sealed. Nobody can see the call early, and nobody (you included) can
// change it after the fact.
//
// The twist that makes the record honest: a call that is not revealed by
// its own deadline is publicly marked "ducked" on the author's track
// record, so you cannot seal ten guesses and only reveal the one that
// landed. Once revealed, other accounts give a verdict (held / missed).
package receipts

import (
	"chain"
	"chain/runtime"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

const (
	MaxTopicLen      = 120
	MaxPredictionLen = 560
	MinSaltLen       = 8
	MaxSaltLen       = 64
	MinRevealDays    = 1
	MaxRevealDays    = 3650
	Separator        = "|"
)

// Call is one sealed prediction.
type Call struct {
	ID         int
	Author     address
	Topic      string
	Commitment string // lowercase hex sha256(salt + "|" + prediction)

	SealedHeight int64
	SealedAt     time.Time
	RevealBy     time.Time

	Revealed       bool
	Prediction     string
	Salt           string
	RevealedHeight int64
	RevealedAt     time.Time

	Held   int
	Missed int
	votes  *avl.Tree // voter address -> "held" | "missed"
}

type author struct {
	calls []int
}

var (
	ids     seqid.ID
	calls   avl.Tree // seqid binary -> *Call
	authors avl.Tree // address string -> *author
)

// Commit returns the commitment for a prediction and salt:
// lowercase hex of sha256(salt + "|" + prediction).
// It is a plain read helper; compute it off-chain if the text is secret.
func Commit(prediction, salt string) string {
	sum := sha256.Sum256([]byte(salt + Separator + prediction))
	return hex.EncodeToString(sum[:])
}

// Seal publishes a commitment. topic is public (e.g. "BTC close on Dec 31"),
// commitment is the 64-char hex hash, revealByDays is the deadline you
// promise to reveal by. Returns the new call ID.
func Seal(cur realm, topic, commitment string, revealByDays int) int {
	caller := cur.Previous().Address()
	topic = strings.TrimSpace(topic)
	if topic == "" {
		panic("topic is required")
	}
	if len(topic) > MaxTopicLen {
		panic("topic is longer than " + strconv.Itoa(MaxTopicLen) + " bytes")
	}
	commitment = strings.ToLower(strings.TrimSpace(commitment))
	if !isHex64(commitment) {
		panic("commitment must be 64 hex characters (sha256)")
	}
	if revealByDays < MinRevealDays || revealByDays > MaxRevealDays {
		panic("revealByDays must be between 1 and 3650")
	}

	now := time.Now()
	id := int(ids.Next())
	c := &Call{
		ID:           id,
		Author:       caller,
		Topic:        topic,
		Commitment:   commitment,
		SealedHeight: chainHeight(),
		SealedAt:     now,
		RevealBy:     now.Add(time.Duration(revealByDays) * 24 * time.Hour),
		votes:        avl.NewTree(),
	}
	calls.Set(key(id), c)

	a := getAuthor(caller)
	if a == nil {
		a = &author{}
		authors.Set(caller.String(), a)
	}
	a.calls = append(a.calls, id)

	chain.Emit("Sealed",
		"id", strconv.Itoa(id),
		"author", caller.String(),
		"commitment", commitment,
	)
	return id
}

// Reveal opens a sealed call. Only its author can reveal it. The realm
// re-computes sha256(salt + "|" + prediction) and refuses on mismatch.
func Reveal(cur realm, id int, prediction, salt string) {
	caller := cur.Previous().Address()
	c := mustGet(id)
	if c.Author != caller {
		panic("only the author can reveal this call")
	}
	if c.Revealed {
		panic("call already revealed")
	}
	if len(salt) < MinSaltLen || len(salt) > MaxSaltLen {
		panic("salt must be 8 to 64 bytes")
	}
	if len(prediction) == 0 || len(prediction) > MaxPredictionLen {
		panic("prediction must be 1 to " + strconv.Itoa(MaxPredictionLen) + " bytes")
	}
	if Commit(prediction, salt) != c.Commitment {
		panic("prediction and salt do not match the sealed commitment")
	}
	c.Revealed = true
	c.Prediction = prediction
	c.Salt = salt
	c.RevealedHeight = chainHeight()
	c.RevealedAt = time.Now()

	chain.Emit("Revealed",
		"id", strconv.Itoa(id),
		"author", caller.String(),
		"onTime", strconv.FormatBool(!c.RevealedAt.After(c.RevealBy)),
	)
}

// Verdict records whether a revealed call came true. verdict is "held" or
// "missed". One verdict per account per call; calling again changes it.
// Authors cannot judge their own calls.
func Verdict(cur realm, id int, verdict string) {
	caller := cur.Previous().Address()
	c := mustGet(id)
	if !c.Revealed {
		panic("call is still sealed")
	}
	if c.Author == caller {
		panic("authors cannot judge their own call")
	}
	verdict = strings.ToLower(strings.TrimSpace(verdict))
	if verdict != "held" && verdict != "missed" {
		panic(`verdict must be "held" or "missed"`)
	}
	k := caller.String()
	if prev := c.votes.Get(k); prev != nil {
		if prev.(string) == verdict {
			return
		}
		if prev.(string) == "held" {
			c.Held--
		} else {
			c.Missed--
		}
	}
	c.votes.Set(k, verdict)
	if verdict == "held" {
		c.Held++
	} else {
		c.Missed++
	}
	chain.Emit("Verdict", "id", strconv.Itoa(id), "voter", k, "verdict", verdict)
}

// Status values for a call at the current block time.
const (
	StatusSealed   = "sealed"
	StatusDucked   = "ducked"
	StatusRevealed = "revealed"
	StatusLate     = "revealed late"
)

// StatusOf returns the call's status at the current block time.
func StatusOf(id int) string {
	return mustGet(id).status(time.Now())
}

// GetCall returns a copy of a call's public fields, for clients (vm/qeval).
func GetCall(id int) (author address, topic, commitment, status, prediction string, sealedHeight int64, revealBy string, held, missed int) {
	c := mustGet(id)
	return c.Author, c.Topic, c.Commitment, c.status(time.Now()), c.Prediction,
		c.SealedHeight, c.RevealBy.UTC().Format(time.RFC3339), c.Held, c.Missed
}

// Count returns how many calls have been sealed.
func Count() int { return calls.Size() }

func (c *Call) status(now time.Time) string {
	if c.Revealed {
		if c.RevealedAt.After(c.RevealBy) {
			return StatusLate
		}
		return StatusRevealed
	}
	if now.After(c.RevealBy) {
		return StatusDucked
	}
	return StatusSealed
}

// Outcome is the crowd verdict on a revealed call: "held", "missed",
// "split" or "" (no verdicts yet).
func (c *Call) outcome() string {
	switch {
	case c.Held == 0 && c.Missed == 0:
		return ""
	case c.Held > c.Missed:
		return "held"
	case c.Missed > c.Held:
		return "missed"
	}
	return "split"
}

func mustGet(id int) *Call {
	v := calls.Get(key(id))
	if v == nil {
		panic("call " + strconv.Itoa(id) + " not found")
	}
	return v.(*Call)
}

func getCall(id int) *Call {
	v := calls.Get(key(id))
	if v == nil {
		return nil
	}
	return v.(*Call)
}

func getAuthor(a address) *author {
	v := authors.Get(a.String())
	if v == nil {
		return nil
	}
	return v.(*author)
}

func key(id int) string { return seqid.ID(id).Binary() }

func isHex64(s string) bool {
	if len(s) != 64 {
		return false
	}
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if !(ch >= '0' && ch <= '9' || ch >= 'a' && ch <= 'f') {
			return false
		}
	}
	return true
}

func chainHeight() int64 { return runtime.ChainHeight() }

package receipts

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
	carol = testutils.TestAddress("carol")
)

const (
	call1 = "GNOT trades above $1 before June 1, 2027"
	salt1 = "q7Zp-4tLx9"
)

func TestCommitKnownVector(t *testing.T) {
	// printf '%s|%s' 'saltsalt' 'hello' | sha256sum
	got := Commit("hello", "saltsalt")
	uassert.Equal(t, "ae4bd9fb4bcccb6edaed2ac2f1bdbd189efef96f98aa12ca78f4ae44a6fbd832", got)
	uassert.Equal(t, 64, len(got))
	uassert.Equal(t, got, Commit("hello", "saltsalt"))
	uassert.NotEqual(t, got, Commit("hello ", "saltsalt"))
}

func TestFullLifecycle(cur realm, t *testing.T) {
	commitment := Commit(call1, salt1)

	testing.SetRealm(testing.NewUserRealm(alice))
	id := Seal(cross(cur), "GNOT price by mid 2027", commitment, 30)
	uassert.Equal(t, 1, id)
	uassert.Equal(t, StatusSealed, StatusOf(id))

	// The prediction is not on-chain yet.
	page := Render("call/1")
	uassert.False(t, strings.Contains(page, "GNOT trades above"))
	uassert.True(t, strings.Contains(page, commitment))

	// Bob cannot reveal Alice's call.
	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsWithMessage(t, cur, "only the author can reveal this call", func() {
		Reveal(cross(cur), id, call1, salt1)
	})

	// Wrong text is refused.
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsWithMessage(t, cur, "prediction and salt do not match the sealed commitment", func() {
		Reveal(cross(cur), id, "GNOT trades above $2 before June 1, 2027", salt1)
	})

	// Verdicts are refused while sealed.
	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsWithMessage(t, cur, "call is still sealed", func() {
		Verdict(cross(cur), id, "held")
	})

	testing.SetRealm(testing.NewUserRealm(alice))
	Reveal(cross(cur), id, call1, salt1)
	uassert.Equal(t, StatusRevealed, StatusOf(id))

	// Author cannot judge own call.
	uassert.AbortsWithMessage(t, cur, "authors cannot judge their own call", func() {
		Verdict(cross(cur), id, "held")
	})

	testing.SetRealm(testing.NewUserRealm(bob))
	Verdict(cross(cur), id, "held")
	testing.SetRealm(testing.NewUserRealm(carol))
	Verdict(cross(cur), id, "missed")
	// Carol changes her mind; counts move, no double vote.
	testing.SetRealm(testing.NewUserRealm(carol))
	Verdict(cross(cur), id, "held")

	_, _, _, status, prediction, _, _, held, missed := GetCall(id)
	uassert.Equal(t, StatusRevealed, status)
	uassert.Equal(t, call1, prediction)
	uassert.Equal(t, 2, held)
	uassert.Equal(t, 0, missed)

	r := TrackRecord(alice)
	uassert.Equal(t, 1, r.Sealed)
	uassert.Equal(t, 1, r.OnTime)
	uassert.Equal(t, 1, r.Held)
	uassert.Equal(t, 100, r.KeptWord())

	page = Render("call/1")
	uassert.True(t, strings.Contains(page, "Verified on-chain"))
	// "$" from user text is escaped so gnoweb does not render math.
	uassert.True(t, strings.Contains(page, "\\$1"))
}

func TestValidation(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsWithMessage(t, cur, "commitment must be 64 hex characters (sha256)", func() {
		Seal(cross(cur), "topic", "abc", 3)
	})
	uassert.AbortsWithMessage(t, cur, "topic is required", func() {
		Seal(cross(cur), "   ", Commit("x", "12345678"), 3)
	})
	uassert.AbortsWithMessage(t, cur, "revealByDays must be between 1 and 3650", func() {
		Seal(cross(cur), "topic", Commit("x", "12345678"), 0)
	})
	id := Seal(cross(cur), "short salt", Commit("yes", "abc"), 3)
	uassert.AbortsWithMessage(t, cur, "salt must be 8 to 64 bytes", func() {
		Reveal(cross(cur), id, "yes", "abc")
	})
	uassert.AbortsWithMessage(t, cur, `verdict must be "held" or "missed"`, func() {
		testing.SetRealm(testing.NewUserRealm(carol))
		Verdict(cross(cur), 1, "maybe")
	})
}

func TestDuckedAfterDeadline(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(carol))
	id := Seal(cross(cur), "will be ducked", Commit("rain tomorrow", "saltysalt"), 1)
	uassert.Equal(t, StatusSealed, StatusOf(id))
	// ~5s blocks: skip well past one day.
	testing.SkipHeights(30000)
	uassert.Equal(t, StatusDucked, StatusOf(id))
	r := TrackRecord(carol)
	uassert.Equal(t, 1, r.Ducked)
	uassert.Equal(t, 0, r.KeptWord())

	// A late reveal is accepted but stays marked late.
	testing.SetRealm(testing.NewUserRealm(carol))
	Reveal(cross(cur), id, "rain tomorrow", "saltysalt")
	uassert.Equal(t, StatusLate, StatusOf(id))
	uassert.True(t, strings.Contains(Render("board"), "Track records"))
	uassert.True(t, strings.Contains(Render(""), "will be ducked"))
	uassert.True(t, strings.Contains(Render("u/"+carol.String()), "revealed late"))
}

func TestRenderUnknown(t *testing.T) {
	uassert.True(t, strings.Contains(Render("call/9999"), "Call not found"))
	uassert.True(t, strings.Contains(Render("u/notanaddress"), "not a valid address"))
	uassert.True(t, strings.Contains(Render("how"), "How it works"))
	uassert.True(t, strings.Contains(Render("nope/nope"), "Not found"))
}

package receipts

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/mux/v0"
)

// SealerURL is an offline page that computes a commitment in your browser.
const SealerURL = "https://666crypro.github.io/receipts/"

var router *mux.Router

func init() {
	router = mux.NewRouter()
	router.HandleFunc("", renderHome)
	router.HandleFunc("call/{id}", renderCall)
	router.HandleFunc("u/{addr}", renderAuthor)
	router.HandleFunc("board", renderBoard)
	router.HandleFunc("how", renderHow)
	router.SetNotFoundHandler(func(res *mux.ResponseWriter, req *mux.Request) {
		res.Write("# Not found\n\nNo page here. [Back to Receipts](" + homeLink + ")\n")
	})
}

const homeLink = "/r/nym-receipts001/receipts"

// Render serves the gnoweb pages.
func Render(path string) string {
	return router.Render(path)
}

func renderHome(res *mux.ResponseWriter, req *mux.Request) {
	now := time.Now()
	var sealed, revealed, ducked int
	calls.Iterate("", "", func(_ string, v any) bool {
		switch v.(*Call).status(now) {
		case StatusSealed:
			sealed++
		case StatusDucked:
			ducked++
		default:
			revealed++
		}
		return false
	})

	var b strings.Builder
	b.WriteString("# Receipts\n\n")
	b.WriteString("**Call it now. Prove it later.** Seal a prediction as a hash today; reveal it when the time comes. ")
	b.WriteString("The chain stamps when you sealed it, so nobody can say you made it up afterwards. ")
	b.WriteString("Miss your own reveal deadline and the call is marked **ducked** on your record, so cherry-picking shows.\n\n")

	b.WriteString("| Sealed calls | Revealed | Ducked | Authors |\n|---:|---:|---:|---:|\n")
	b.WriteString("| " + strconv.Itoa(sealed) + " | " + strconv.Itoa(revealed) + " | " + strconv.Itoa(ducked) + " | " + strconv.Itoa(authors.Size()) + " |\n\n")

	b.WriteString("<gno-button href=\"" + SealerURL + "\" label=\"1. Make a commitment (offline)\" />")
	b.WriteString(" <gno-button href=\"" + homeLink + ":board\" label=\"Track records\" variant=\"outline\" />")
	b.WriteString(" <gno-button href=\"" + homeLink + ":how\" label=\"How it works\" variant=\"outline\" />\n\n")

	b.WriteString("## Seal a call\n\n")
	b.WriteString("Paste the commitment from the sealer (or run `printf '%s|%s' \"$SALT\" \"$CALL\" | sha256sum`). Your text never touches the chain until you reveal it.\n\n")
	b.WriteString("<gno-form exec=\"Seal\">\n")
	b.WriteString("<gno-input name=\"topic\" placeholder=\"Public topic, e.g. Who wins the Dec 31 vote\" required=\"true\" />\n")
	b.WriteString("<gno-input name=\"commitment\" placeholder=\"Commitment: 64 hex characters\" required=\"true\" />\n")
	b.WriteString("<gno-input name=\"revealByDays\" type=\"number\" placeholder=\"Reveal within (days)\" value=\"30\" required=\"true\" />\n")
	b.WriteString("</gno-form>\n\n")

	b.WriteString("## Latest calls\n\n")
	if calls.Size() == 0 {
		b.WriteString("_No calls yet. Be the first._\n")
	} else {
		b.WriteString(callTableHeader)
		calls.ReverseIterateByOffset(0, 15, func(_ string, v any) bool {
			b.WriteString(callRow(v.(*Call), now))
			return false
		})
	}
	res.Write(b.String())
}

const callTableHeader = "| # | Topic | Author | Status | Sealed at block |\n|---:|---|---|---|---:|\n"

func callRow(c *Call, now time.Time) string {
	return "| [" + strconv.Itoa(c.ID) + "](" + callLink(c.ID) + ") | " +
		"[" + escDollar(sanitize.TableCell(c.Topic)) + "](" + callLink(c.ID) + ") | " +
		shortAddr(c.Author) + " | " + badge(c, now) + " | " +
		strconv.FormatInt(c.SealedHeight, 10) + " |\n"
}

func renderCall(res *mux.ResponseWriter, req *mux.Request) {
	id, err := strconv.Atoi(req.GetVar("id"))
	c := getCall(id)
	if err != nil || c == nil {
		res.Write("# Call not found\n\n[Back to Receipts](" + homeLink + ")\n")
		return
	}
	now := time.Now()
	var b strings.Builder
	b.WriteString("[Receipts](" + homeLink + ") / Call #" + strconv.Itoa(c.ID) + "\n\n")
	b.WriteString("# " + escDollar(sanitize.InlineText(c.Topic)) + "\n\n")
	b.WriteString("**" + badge(c, now) + "** · by [" + c.Author.String() + "](" + homeLink + ":u/" + c.Author.String() + ")\n\n")

	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| Sealed | block " + strconv.FormatInt(c.SealedHeight, 10) + " · " + fmtTime(c.SealedAt) + " |\n")
	b.WriteString("| Reveal by | " + fmtTime(c.RevealBy) + dueIn(c, now) + " |\n")
	if c.Revealed {
		b.WriteString("| Revealed | block " + strconv.FormatInt(c.RevealedHeight, 10) + " · " + fmtTime(c.RevealedAt) + " |\n")
	}
	b.WriteString("| Commitment | `" + c.Commitment + "` |\n\n")

	if c.Revealed {
		b.WriteString("## The call\n\n")
		b.WriteString(escDollar(sanitize.Blockquote(c.Prediction)) + "\n\n")
		b.WriteString("> [!SUCCESS] Verified on-chain\n")
		b.WriteString("> `sha256(salt + \"|\" + call)` equals the commitment sealed at block " +
			strconv.FormatInt(c.SealedHeight, 10) + ", " + blocksBetween(c) + " before the reveal. Salt: " +
			escDollar(sanitize.InlineCode(c.Salt)) + "\n\n")

		b.WriteString("## Did it hold?\n\n")
		b.WriteString("Held **" + strconv.Itoa(c.Held) + "** · Missed **" + strconv.Itoa(c.Missed) + "**")
		if o := c.outcome(); o != "" {
			b.WriteString(" · crowd says **" + o + "**")
		}
		b.WriteString("\n\nAnyone except the author can give one verdict (and change it later).\n\n")
		b.WriteString("<gno-form exec=\"Verdict\">\n")
		b.WriteString("<gno-input name=\"id\" type=\"number\" value=\"" + strconv.Itoa(c.ID) + "\" placeholder=\"Call ID\" readonly=\"true\" />\n")
		b.WriteString("<gno-input name=\"verdict\" type=\"radio\" value=\"held\" placeholder=\"Held: it came true\" />\n")
		b.WriteString("<gno-input name=\"verdict\" type=\"radio\" value=\"missed\" placeholder=\"Missed: it did not\" />\n")
		b.WriteString("</gno-form>\n")
	} else {
		if c.status(now) == StatusDucked {
			b.WriteString("> [!WARNING] Ducked\n> The author promised to reveal this call by " + fmtTime(c.RevealBy) +
				" and has not. It counts against their track record until revealed, and a late reveal stays marked late.\n\n")
		} else {
			b.WriteString("> [!NOTE] Still sealed\n> Only the hash is public. The author reveals the exact text and salt; the realm checks the hash.\n\n")
		}
		b.WriteString("## Reveal (author only)\n\n")
		b.WriteString("<gno-form exec=\"Reveal\">\n")
		b.WriteString("<gno-input name=\"id\" type=\"number\" value=\"" + strconv.Itoa(c.ID) + "\" placeholder=\"Call ID\" readonly=\"true\" />\n")
		b.WriteString("<gno-textarea name=\"prediction\" rows=\"3\" placeholder=\"The exact call text you sealed\" />\n")
		b.WriteString("<gno-input name=\"salt\" placeholder=\"The exact salt you sealed with\" />\n")
		b.WriteString("</gno-form>\n")
	}
	res.Write(b.String())
}

// Record is an author's track record.
type Record struct {
	Author                             address
	Sealed, Open, OnTime, Late, Ducked int
	Held, Missed                       int
}

// KeptWord is the share of due calls revealed on time, in percent, or -1
// when nothing is due yet.
func (r Record) KeptWord() int {
	due := r.OnTime + r.Late + r.Ducked
	if due == 0 {
		return -1
	}
	return r.OnTime * 100 / due
}

func recordOf(a address, now time.Time) Record {
	r := Record{Author: a}
	au := getAuthor(a)
	if au == nil {
		return r
	}
	for _, id := range au.calls {
		c := getCall(id)
		r.Sealed++
		switch c.status(now) {
		case StatusSealed:
			r.Open++
		case StatusDucked:
			r.Ducked++
		case StatusLate:
			r.Late++
		case StatusRevealed:
			r.OnTime++
		}
		switch c.outcome() {
		case "held":
			r.Held++
		case "missed":
			r.Missed++
		}
	}
	return r
}

// TrackRecord returns an author's record, for clients (vm/qeval).
func TrackRecord(a address) Record { return recordOf(a, time.Now()) }

func renderAuthor(res *mux.ResponseWriter, req *mux.Request) {
	raw := req.GetVar("addr")
	a := address(raw)
	if !a.IsValid() {
		res.Write("# Unknown author\n\nThat is not a valid address. [Back](" + homeLink + ")\n")
		return
	}
	now := time.Now()
	r := recordOf(a, now)
	var b strings.Builder
	b.WriteString("[Receipts](" + homeLink + ") / Track record\n\n")
	b.WriteString("# " + a.String() + "\n\n")
	b.WriteString(recordHeader)
	b.WriteString(recordRow(r, false))
	b.WriteString("\n")
	au := getAuthor(a)
	if au == nil {
		b.WriteString("_No calls sealed by this address yet._\n")
		res.Write(b.String())
		return
	}
	b.WriteString("## Calls\n\n" + callTableHeader)
	for i := len(au.calls) - 1; i >= 0; i-- {
		b.WriteString(callRow(getCall(au.calls[i]), now))
	}
	res.Write(b.String())
}

const recordHeader = "| Author | Sealed | Open | On time | Late | Ducked | Kept word | Held | Missed |\n|---|---:|---:|---:|---:|---:|---:|---:|---:|\n"

func recordRow(r Record, link bool) string {
	who := shortAddr(r.Author)
	if !link {
		who = "this address"
	}
	kw := "n/a"
	if k := r.KeptWord(); k >= 0 {
		kw = strconv.Itoa(k) + "%"
	}
	return "| " + who + " | " + strconv.Itoa(r.Sealed) + " | " + strconv.Itoa(r.Open) + " | " +
		strconv.Itoa(r.OnTime) + " | " + strconv.Itoa(r.Late) + " | " + strconv.Itoa(r.Ducked) + " | " +
		kw + " | " + strconv.Itoa(r.Held) + " | " + strconv.Itoa(r.Missed) + " |\n"
}

// better reports whether record x ranks above y: more held calls first,
// then a higher kept-word rate, then fewer ducked calls, then more sealed.
func better(x, y Record) bool {
	if x.Held != y.Held {
		return x.Held > y.Held
	}
	if x.KeptWord() != y.KeptWord() {
		return x.KeptWord() > y.KeptWord()
	}
	if x.Ducked != y.Ducked {
		return x.Ducked < y.Ducked
	}
	return x.Sealed > y.Sealed
}

// Leaderboard returns up to n records, best first.
func Leaderboard(n int) []Record {
	now := time.Now()
	var rs []Record
	authors.Iterate("", "", func(k string, _ any) bool {
		r := recordOf(address(k), now)
		// insertion sort: the author set is small and this is a read path
		i := len(rs)
		rs = append(rs, r)
		for i > 0 && better(rs[i], rs[i-1]) {
			rs[i], rs[i-1] = rs[i-1], rs[i]
			i--
		}
		return false
	})
	if n >= 0 && len(rs) > n {
		rs = rs[:n]
	}
	return rs
}

func renderBoard(res *mux.ResponseWriter, req *mux.Request) {
	var b strings.Builder
	b.WriteString("[Receipts](" + homeLink + ") / Track records\n\n# Track records\n\n")
	b.WriteString("Ranked by calls the crowd says **held**, then **kept word** (share of due calls revealed on time), then fewest **ducked**.\n\n")
	rs := Leaderboard(50)
	if len(rs) == 0 {
		b.WriteString("_Nobody has sealed a call yet._\n")
		res.Write(b.String())
		return
	}
	b.WriteString(recordHeader)
	for _, r := range rs {
		row := recordRow(r, true)
		row = strings.Replace(row, shortAddr(r.Author), "["+shortAddr(r.Author)+"]("+homeLink+":u/"+r.Author.String()+")", 1)
		b.WriteString(row)
	}
	res.Write(b.String())
}

func renderHow(res *mux.ResponseWriter, req *mux.Request) {
	res.Write(`[Receipts](` + homeLink + `) / How it works

# How it works

1. **Write your call** and pick a random **salt** (8 to 64 characters). The salt stops anyone from guessing short calls like "yes" by brute force.
2. **Compute the commitment** off-chain: lowercase hex of ` + "`sha256(salt + \"|\" + call)`" + `. Use the [offline sealer](` + SealerURL + `) or:
   ` + "`printf '%s|%s' \"$SALT\" \"$CALL\" | sha256sum`" + `
3. **Seal** it with a public topic and a reveal deadline in days. The chain records the block height and time.
4. **Reveal** any time before the deadline by sending the exact call and salt. The realm re-hashes them and only accepts an exact match.
5. **Verdicts.** Once revealed, other accounts mark it **held** or **missed**. One verdict per account, changeable.

## Statuses

| Status | Meaning |
|---|---|
| sealed | hash public, call hidden, deadline not passed |
| revealed | opened on or before the deadline and verified |
| revealed late | opened after the deadline: verified, but it does not count as kept word |
| ducked | deadline passed, still not revealed: counts against the author |

## For developers

Read-only helpers for clients via ` + "`vm/qeval`" + `: ` + "`Commit(call, salt)`, `GetCall(id)`, `StatusOf(id)`, `TrackRecord(addr)`, `Leaderboard(n)`, `Count()`" + `. Events: ` + "`Sealed`, `Revealed`, `Verdict`" + `.
`)
}

func badge(c *Call, now time.Time) string {
	switch c.status(now) {
	case StatusSealed:
		return "🔒 sealed"
	case StatusDucked:
		return "🫥 ducked"
	case StatusLate:
		s := "⏰ revealed late"
		if o := c.outcome(); o != "" {
			s += ", " + o
		}
		return s
	}
	s := "✅ revealed"
	if o := c.outcome(); o != "" {
		s += ", " + o
	}
	return s
}

func dueIn(c *Call, now time.Time) string {
	if c.Revealed || now.After(c.RevealBy) {
		return ""
	}
	d := c.RevealBy.Sub(now)
	days := int(d.Hours()) / 24
	hours := int(d.Hours()) % 24
	return " (in " + strconv.Itoa(days) + "d " + strconv.Itoa(hours) + "h)"
}

func blocksBetween(c *Call) string {
	n := c.RevealedHeight - c.SealedHeight
	if n == 1 {
		return "1 block"
	}
	return strconv.FormatInt(n, 10) + " blocks"
}

func callLink(id int) string { return homeLink + ":call/" + strconv.Itoa(id) }

func fmtTime(t time.Time) string { return t.UTC().Format("2006-01-02 15:04 UTC") }

func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 14 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

func escDollar(s string) string { return strings.ReplaceAll(s, "$", "\\$") }

// Package receipts is a public ledger of sealed predictions.
//
// You seal a call today by publishing only a SHA-256 commitment of it,
// plus a public topic and a date by which you promise to reveal it.
// Later you reveal the exact text and salt; the realm re-hashes them and
// stamps the call as verified, with the block height and time it was
// sealed. Nobody can see the call early, and nobody (you included) can
// change it after the fact.
//
// The twist that makes the record honest: a call that is not revealed by
// its own deadline is publicly marked "ducked" on the author's track
// record, so you cannot seal ten guesses and only reveal the one that
// landed. Once revealed, other accounts give a verdict (held / missed).
package receipts

import (
	"chain"
	"chain/runtime"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
)

const (
	MaxTopicLen      = 120
	MaxPredictionLen = 560
	MinSaltLen       = 8
	MaxSaltLen       = 64
	MinRevealDays    = 1
	MaxRevealDays    = 3650
	Separator        = "|"
)

// Call is one sealed prediction.
type Call struct {
	ID         int
	Author     address
	Topic      string
	Commitment string // lowercase hex sha256(salt + "|" + prediction)

	SealedHeight int64
	SealedAt     time.Time
	RevealBy     time.Time

	Revealed       bool
	Prediction     string
	Salt           string
	RevealedHeight int64
	RevealedAt     time.Time

	Held   int
	Missed int
	votes  *avl.Tree // voter address -> "held" | "missed"
}

type author struct {
	calls []int
}

var (
	ids     seqid.ID
	calls   avl.Tree // seqid binary -> *Call
	authors avl.Tree // address string -> *author
)

// Commit returns the commitment for a prediction and salt:
// lowercase hex of sha256(salt + "|" + prediction).
// It is a plain read helper; compute it off-chain if the text is secret.
func Commit(prediction, salt string) string {
	sum := sha256.Sum256([]byte(salt + Separator + prediction))
	return hex.EncodeToString(sum[:])
}

// Seal publishes a commitment. topic is public (e.g. "BTC close on Dec 31"),
// commitment is the 64-char hex hash, revealByDays is the deadline you
// promise to reveal by. Returns the new call ID.
func Seal(cur realm, topic, commitment string, revealByDays int) int {
	caller := cur.Previous().Address()
	topic = strings.TrimSpace(topic)
	if topic == "" {
		panic("topic is required")
	}
	if len(topic) > MaxTopicLen {
		panic("topic is longer than " + strconv.Itoa(MaxTopicLen) + " bytes")
	}
	commitment = strings.ToLower(strings.TrimSpace(commitment))
	if !isHex64(commitment) {
		panic("commitment must be 64 hex characters (sha256)")
	}
	if revealByDays < MinRevealDays || revealByDays > MaxRevealDays {
		panic("revealByDays must be between 1 and 3650")
	}

	now := time.Now()
	id := int(ids.Next())
	c := &Call{
		ID:           id,
		Author:       caller,
		Topic:        topic,
		Commitment:   commitment,
		SealedHeight: chainHeight(),
		SealedAt:     now,
		RevealBy:     now.Add(time.Duration(revealByDays) * 24 * time.Hour),
		votes:        avl.NewTree(),
	}
	calls.Set(key(id), c)

	a := getAuthor(caller)
	if a == nil {
		a = &author{}
		authors.Set(caller.String(), a)
	}
	a.calls = append(a.calls, id)

	chain.Emit("Sealed",
		"id", strconv.Itoa(id),
		"author", caller.String(),
		"commitment", commitment,
	)
	return id
}

// Reveal opens a sealed call. Only its author can reveal it. The realm
// re-computes sha256(salt + "|" + prediction) and refuses on mismatch.
func Reveal(cur realm, id int, prediction, salt string) {
	caller := cur.Previous().Address()
	c := mustGet(id)
	if c.Author != caller {
		panic("only the author can reveal this call")
	}
	if c.Revealed {
		panic("call already revealed")
	}
	if len(salt) < MinSaltLen || len(salt) > MaxSaltLen {
		panic("salt must be 8 to 64 bytes")
	}
	if len(prediction) == 0 || len(prediction) > MaxPredictionLen {
		panic("prediction must be 1 to " + strconv.Itoa(MaxPredictionLen) + " bytes")
	}
	if Commit(prediction, salt) != c.Commitment {
		panic("prediction and salt do not match the sealed commitment")
	}
	c.Revealed = true
	c.Prediction = prediction
	c.Salt = salt
	c.RevealedHeight = chainHeight()
	c.RevealedAt = time.Now()

	chain.Emit("Revealed",
		"id", strconv.Itoa(id),
		"author", caller.String(),
		"onTime", strconv.FormatBool(!c.RevealedAt.After(c.RevealBy)),
	)
}

// Verdict records whether a revealed call came true. verdict is "held" or
// "missed". One verdict per account per call; calling again changes it.
// Authors cannot judge their own calls.
func Verdict(cur realm, id int, verdict string) {
	caller := cur.Previous().Address()
	c := mustGet(id)
	if !c.Revealed {
		panic("call is still sealed")
	}
	if c.Author == caller {
		panic("authors cannot judge their own call")
	}
	verdict = strings.ToLower(strings.TrimSpace(verdict))
	if verdict != "held" && verdict != "missed" {
		panic(`verdict must be "held" or "missed"`)
	}
	k := caller.String()
	if prev := c.votes.Get(k); prev != nil {
		if prev.(string) == verdict {
			return
		}
		if prev.(string) == "held" {
			c.Held--
		} else {
			c.Missed--
		}
	}
	c.votes.Set(k, verdict)
	if verdict == "held" {
		c.Held++
	} else {
		c.Missed++
	}
	chain.Emit("Verdict", "id", strconv.Itoa(id), "voter", k, "verdict", verdict)
}

// Status values for a call at the current block time.
const (
	StatusSealed   = "sealed"
	StatusDucked   = "ducked"
	StatusRevealed = "revealed"
	StatusLate     = "revealed late"
)

// StatusOf returns the call's status at the current block time.
func StatusOf(id int) string {
	return mustGet(id).status(time.Now())
}

// GetCall returns a copy of a call's public fields, for clients (vm/qeval).
func GetCall(id int) (author address, topic, commitment, status, prediction string, sealedHeight int64, revealBy string, held, missed int) {
	c := mustGet(id)
	return c.Author, c.Topic, c.Commitment, c.status(time.Now()), c.Prediction,
		c.SealedHeight, c.RevealBy.UTC().Format(time.RFC3339), c.Held, c.Missed
}

// Count returns how many calls have been sealed.
func Count() int { return calls.Size() }

func (c *Call) status(now time.Time) string {
	if c.Revealed {
		if c.RevealedAt.After(c.RevealBy) {
			return StatusLate
		}
		return StatusRevealed
	}
	if now.After(c.RevealBy) {
		return StatusDucked
	}
	return StatusSealed
}

// Outcome is the crowd verdict on a revealed call: "held", "missed",
// "split" or "" (no verdicts yet).
func (c *Call) outcome() string {
	switch {
	case c.Held == 0 && c.Missed == 0:
		return ""
	case c.Held > c.Missed:
		return "held"
	case c.Missed > c.Held:
		return "missed"
	}
	return "split"
}

func mustGet(id int) *Call {
	v := calls.Get(key(id))
	if v == nil {
		panic("call " + strconv.Itoa(id) + " not found")
	}
	return v.(*Call)
}

func getCall(id int) *Call {
	v := calls.Get(key(id))
	if v == nil {
		return nil
	}
	return v.(*Call)
}

func getAuthor(a address) *author {
	v := authors.Get(a.String())
	if v == nil {
		return nil
	}
	return v.(*author)
}

func key(id int) string { return seqid.ID(id).Binary() }

func isHex64(s string) bool {
	if len(s) != 64 {
		return false
	}
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if !(ch >= '0' && ch <= '9' || ch >= 'a' && ch <= 'f') {
			return false
		}
	}
	return true
}

func chainHeight() int64 { return runtime.ChainHeight() }

package receipts

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
	carol = testutils.TestAddress("carol")
)

const (
	call1 = "GNOT trades above $1 before June 1, 2027"
	salt1 = "q7Zp-4tLx9"
)

func TestCommitKnownVector(t *testing.T) {
	// printf '%s|%s' 'saltsalt' 'hello' | sha256sum
	got := Commit("hello", "saltsalt")
	uassert.Equal(t, "ae4bd9fb4bcccb6edaed2ac2f1bdbd189efef96f98aa12ca78f4ae44a6fbd832", got)
	uassert.Equal(t, 64, len(got))
	uassert.Equal(t, got, Commit("hello", "saltsalt"))
	uassert.NotEqual(t, got, Commit("hello ", "saltsalt"))
}

func TestFullLifecycle(cur realm, t *testing.T) {
	commitment := Commit(call1, salt1)

	testing.SetRealm(testing.NewUserRealm(alice))
	id := Seal(cross(cur), "GNOT price by mid 2027", commitment, 30)
	uassert.Equal(t, 1, id)
	uassert.Equal(t, StatusSealed, StatusOf(id))

	// The prediction is not on-chain yet.
	page := Render("call/1")
	uassert.False(t, strings.Contains(page, "GNOT trades above"))
	uassert.True(t, strings.Contains(page, commitment))

	// Bob cannot reveal Alice's call.
	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsWithMessage(t, cur, "only the author can reveal this call", func() {
		Reveal(cross(cur), id, call1, salt1)
	})

	// Wrong text is refused.
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsWithMessage(t, cur, "prediction and salt do not match the sealed commitment", func() {
		Reveal(cross(cur), id, "GNOT trades above $2 before June 1, 2027", salt1)
	})

	// Verdicts are refused while sealed.
	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsWithMessage(t, cur, "call is still sealed", func() {
		Verdict(cross(cur), id, "held")
	})

	testing.SetRealm(testing.NewUserRealm(alice))
	Reveal(cross(cur), id, call1, salt1)
	uassert.Equal(t, StatusRevealed, StatusOf(id))

	// Author cannot judge own call.
	uassert.AbortsWithMessage(t, cur, "authors cannot judge their own call", func() {
		Verdict(cross(cur), id, "held")
	})

	testing.SetRealm(testing.NewUserRealm(bob))
	Verdict(cross(cur), id, "held")
	testing.SetRealm(testing.NewUserRealm(carol))
	Verdict(cross(cur), id, "missed")
	// Carol changes her mind; counts move, no double vote.
	testing.SetRealm(testing.NewUserRealm(carol))
	Verdict(cross(cur), id, "held")

	_, _, _, status, prediction, _, _, held, missed := GetCall(id)
	uassert.Equal(t, StatusRevealed, status)
	uassert.Equal(t, call1, prediction)
	uassert.Equal(t, 2, held)
	uassert.Equal(t, 0, missed)

	r := TrackRecord(alice)
	uassert.Equal(t, 1, r.Sealed)
	uassert.Equal(t, 1, r.OnTime)
	uassert.Equal(t, 1, r.Held)
	uassert.Equal(t, 100, r.KeptWord())

	page = Render("call/1")
	uassert.True(t, strings.Contains(page, "Verified on-chain"))
	// "$" from user text is escaped so gnoweb does not render math.
	uassert.True(t, strings.Contains(page, "\\$1"))
}

func TestValidation(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsWithMessage(t, cur, "commitment must be 64 hex characters (sha256)", func() {
		Seal(cross(cur), "topic", "abc", 3)
	})
	uassert.AbortsWithMessage(t, cur, "topic is required", func() {
		Seal(cross(cur), "   ", Commit("x", "12345678"), 3)
	})
	uassert.AbortsWithMessage(t, cur, "revealByDays must be between 1 and 3650", func() {
		Seal(cross(cur), "topic", Commit("x", "12345678"), 0)
	})
	id := Seal(cross(cur), "short salt", Commit("yes", "abc"), 3)
	uassert.AbortsWithMessage(t, cur, "salt must be 8 to 64 bytes", func() {
		Reveal(cross(cur), id, "yes", "abc")
	})
	uassert.AbortsWithMessage(t, cur, `verdict must be "held" or "missed"`, func() {
		testing.SetRealm(testing.NewUserRealm(carol))
		Verdict(cross(cur), 1, "maybe")
	})
}

func TestDuckedAfterDeadline(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(carol))
	id := Seal(cross(cur), "will be ducked", Commit("rain tomorrow", "saltysalt"), 1)
	uassert.Equal(t, StatusSealed, StatusOf(id))
	// ~5s blocks: skip well past one day.
	testing.SkipHeights(30000)
	uassert.Equal(t, StatusDucked, StatusOf(id))
	r := TrackRecord(carol)
	uassert.Equal(t, 1, r.Ducked)
	uassert.Equal(t, 0, r.KeptWord())

	// A late reveal is accepted but stays marked late.
	testing.SetRealm(testing.NewUserRealm(carol))
	Reveal(cross(cur), id, "rain tomorrow", "saltysalt")
	uassert.Equal(t, StatusLate, StatusOf(id))
	uassert.True(t, strings.Contains(Render("board"), "Track records"))
	uassert.True(t, strings.Contains(Render(""), "will be ducked"))
	uassert.True(t, strings.Contains(Render("u/"+carol.String()), "revealed late"))
}

func TestRenderUnknown(t *testing.T) {
	uassert.True(t, strings.Contains(Render("call/9999"), "Call not found"))
	uassert.True(t, strings.Contains(Render("u/notanaddress"), "not a valid address"))
	uassert.True(t, strings.Contains(Render("how"), "How it works"))
	uassert.True(t, strings.Contains(Render("nope/nope"), "Not found"))
}

package receipts

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/mux/v0"
)

// SealerURL is an offline page that computes a commitment in your browser.
const SealerURL = "https://666crypro.github.io/receipts/"

var router *mux.Router

func init() {
	router = mux.NewRouter()
	router.HandleFunc("", renderHome)
	router.HandleFunc("call/{id}", renderCall)
	router.HandleFunc("u/{addr}", renderAuthor)
	router.HandleFunc("board", renderBoard)
	router.HandleFunc("how", renderHow)
	router.SetNotFoundHandler(func(res *mux.ResponseWriter, req *mux.Request) {
		res.Write("# Not found\n\nNo page here. [Back to Receipts](" + homeLink + ")\n")
	})
}

const homeLink = "/r/nym-receipts001/receipts"

// Render serves the gnoweb pages.
func Render(path string) string {
	return router.Render(path)
}

func renderHome(res *mux.ResponseWriter, req *mux.Request) {
	now := time.Now()
	var sealed, revealed, ducked int
	calls.Iterate("", "", func(_ string, v any) bool {
		switch v.(*Call).status(now) {
		case StatusSealed:
			sealed++
		case StatusDucked:
			ducked++
		default:
			revealed++
		}
		return false
	})

	var b strings.Builder
	b.WriteString("# Receipts\n\n")
	b.WriteString("**Call it now. Prove it later.** Seal a prediction as a hash today; reveal it when the time comes. ")
	b.WriteString("The chain stamps when you sealed it, so nobody can say you made it up afterwards. ")
	b.WriteString("Miss your own reveal deadline and the call is marked **ducked** on your record, so cherry-picking shows.\n\n")

	b.WriteString("| Sealed calls | Revealed | Ducked | Authors |\n|---:|---:|---:|---:|\n")
	b.WriteString("| " + strconv.Itoa(sealed) + " | " + strconv.Itoa(revealed) + " | " + strconv.Itoa(ducked) + " | " + strconv.Itoa(authors.Size()) + " |\n\n")

	b.WriteString("<gno-button href=\"" + SealerURL + "\" label=\"1. Make a commitment (offline)\" />")
	b.WriteString(" <gno-button href=\"" + homeLink + ":board\" label=\"Track records\" variant=\"outline\" />")
	b.WriteString(" <gno-button href=\"" + homeLink + ":how\" label=\"How it works\" variant=\"outline\" />\n\n")

	b.WriteString("## Seal a call\n\n")
	b.WriteString("Paste the commitment from the sealer (or run `printf '%s|%s' \"$SALT\" \"$CALL\" | sha256sum`). Your text never touches the chain until you reveal it.\n\n")
	b.WriteString("<gno-form exec=\"Seal\">\n")
	b.WriteString("<gno-input name=\"topic\" placeholder=\"Public topic, e.g. Who wins the Dec 31 vote\" required=\"true\" />\n")
	b.WriteString("<gno-input name=\"commitment\" placeholder=\"Commitment: 64 hex characters\" required=\"true\" />\n")
	b.WriteString("<gno-input name=\"revealByDays\" type=\"number\" placeholder=\"Reveal within (days)\" value=\"30\" required=\"true\" />\n")
	b.WriteString("</gno-form>\n\n")

	b.WriteString("## Latest calls\n\n")
	if calls.Size() == 0 {
		b.WriteString("_No calls yet. Be the first._\n")
	} else {
		b.WriteString(callTableHeader)
		calls.ReverseIterateByOffset(0, 15, func(_ string, v any) bool {
			b.WriteString(callRow(v.(*Call), now))
			return false
		})
	}
	res.Write(b.String())
}

const callTableHeader = "| # | Topic | Author | Status | Sealed at block |\n|---:|---|---|---|---:|\n"

func callRow(c *Call, now time.Time) string {
	return "| [" + strconv.Itoa(c.ID) + "](" + callLink(c.ID) + ") | " +
		"[" + escDollar(sanitize.TableCell(c.Topic)) + "](" + callLink(c.ID) + ") | " +
		shortAddr(c.Author) + " | " + badge(c, now) + " | " +
		strconv.FormatInt(c.SealedHeight, 10) + " |\n"
}

func renderCall(res *mux.ResponseWriter, req *mux.Request) {
	id, err := strconv.Atoi(req.GetVar("id"))
	c := getCall(id)
	if err != nil || c == nil {
		res.Write("# Call not found\n\n[Back to Receipts](" + homeLink + ")\n")
		return
	}
	now := time.Now()
	var b strings.Builder
	b.WriteString("[Receipts](" + homeLink + ") / Call #" + strconv.Itoa(c.ID) + "\n\n")
	b.WriteString("# " + escDollar(sanitize.InlineText(c.Topic)) + "\n\n")
	b.WriteString("**" + badge(c, now) + "** · by [" + c.Author.String() + "](" + homeLink + ":u/" + c.Author.String() + ")\n\n")

	b.WriteString("| Receipt | |\n|---|---|\n")
	b.WriteString("| Sealed | block " + strconv.FormatInt(c.SealedHeight, 10) + " · " + fmtTime(c.SealedAt) + " |\n")
	b.WriteString("| Reveal by | " + fmtTime(c.RevealBy) + dueIn(c, now) + " |\n")
	if c.Revealed {
		b.WriteString("| Revealed | block " + strconv.FormatInt(c.RevealedHeight, 10) + " · " + fmtTime(c.RevealedAt) + " |\n")
	}
	b.WriteString("| Commitment | `" + c.Commitment + "` |\n\n")

	if c.Revealed {
		b.WriteString("## The call\n\n")
		b.WriteString(escDollar(sanitize.Blockquote(c.Prediction)) + "\n\n")
		b.WriteString("> [!SUCCESS] Verified on-chain\n")
		b.WriteString("> `sha256(salt + \"|\" + call)` equals the commitment sealed at block " +
			strconv.FormatInt(c.SealedHeight, 10) + ", " + blocksBetween(c) + " before the reveal. Salt: " +
			escDollar(sanitize.InlineCode(c.Salt)) + "\n\n")

		b.WriteString("## Did it hold?\n\n")
		b.WriteString("Held **" + strconv.Itoa(c.Held) + "** · Missed **" + strconv.Itoa(c.Missed) + "**")
		if o := c.outcome(); o != "" {
			b.WriteString(" · crowd says **" + o + "**")
		}
		b.WriteString("\n\nAnyone except the author can give one verdict (and change it later).\n\n")
		b.WriteString("<gno-form exec=\"Verdict\">\n")
		b.WriteString("<gno-input name=\"id\" type=\"number\" value=\"" + strconv.Itoa(c.ID) + "\" placeholder=\"Call ID\" readonly=\"true\" />\n")
		b.WriteString("<gno-input name=\"verdict\" type=\"radio\" value=\"held\" placeholder=\"it came true\" />\n")
		b.WriteString("<gno-input name=\"verdict\" type=\"radio\" value=\"missed\" placeholder=\"it did not\" />\n")
		b.WriteString("</gno-form>\n")
	} else {
		if c.status(now) == StatusDucked {
			b.WriteString("> [!WARNING] Ducked\n> The author promised to reveal this call by " + fmtTime(c.RevealBy) +
				" and has not. It counts against their track record until revealed, and a late reveal stays marked late.\n\n")
		} else {
			b.WriteString("> [!NOTE] Still sealed\n> Only the hash is public. The author reveals the exact text and salt; the realm checks the hash.\n\n")
		}
		b.WriteString("## Reveal (author only)\n\n")
		b.WriteString("<gno-form exec=\"Reveal\">\n")
		b.WriteString("<gno-input name=\"id\" type=\"number\" value=\"" + strconv.Itoa(c.ID) + "\" placeholder=\"Call ID\" readonly=\"true\" />\n")
		b.WriteString("<gno-textarea name=\"prediction\" rows=\"3\" placeholder=\"The exact call text you sealed\" />\n")
		b.WriteString("<gno-input name=\"salt\" placeholder=\"The exact salt you sealed with\" />\n")
		b.WriteString("</gno-form>\n")
	}
	res.Write(b.String())
}

// Record is an author's track record.
type Record struct {
	Author                             address
	Sealed, Open, OnTime, Late, Ducked int
	Held, Missed                       int
}

// KeptWord is the share of due calls revealed on time, in percent, or -1
// when nothing is due yet.
func (r Record) KeptWord() int {
	due := r.OnTime + r.Late + r.Ducked
	if due == 0 {
		return -1
	}
	return r.OnTime * 100 / due
}

func recordOf(a address, now time.Time) Record {
	r := Record{Author: a}
	au := getAuthor(a)
	if au == nil {
		return r
	}
	for _, id := range au.calls {
		c := getCall(id)
		r.Sealed++
		switch c.status(now) {
		case StatusSealed:
			r.Open++
		case StatusDucked:
			r.Ducked++
		case StatusLate:
			r.Late++
		case StatusRevealed:
			r.OnTime++
		}
		switch c.outcome() {
		case "held":
			r.Held++
		case "missed":
			r.Missed++
		}
	}
	return r
}

// TrackRecord returns an author's record, for clients (vm/qeval).
func TrackRecord(a address) Record { return recordOf(a, time.Now()) }

func renderAuthor(res *mux.ResponseWriter, req *mux.Request) {
	raw := req.GetVar("addr")
	a := address(raw)
	if !a.IsValid() {
		res.Write("# Unknown author\n\nThat is not a valid address. [Back](" + homeLink + ")\n")
		return
	}
	now := time.Now()
	r := recordOf(a, now)
	var b strings.Builder
	b.WriteString("[Receipts](" + homeLink + ") / Track record\n\n")
	b.WriteString("# " + a.String() + "\n\n")
	b.WriteString(recordHeader)
	b.WriteString(recordRow(r, false))
	b.WriteString("\n")
	au := getAuthor(a)
	if au == nil {
		b.WriteString("_No calls sealed by this address yet._\n")
		res.Write(b.String())
		return
	}
	b.WriteString("## Calls\n\n" + callTableHeader)
	for i := len(au.calls) - 1; i >= 0; i-- {
		b.WriteString(callRow(getCall(au.calls[i]), now))
	}
	res.Write(b.String())
}

const recordHeader = "| Author | Sealed | Open | On time | Late | Ducked | Kept word | Held | Missed |\n|---|---:|---:|---:|---:|---:|---:|---:|---:|\n"

func recordRow(r Record, link bool) string {
	who := shortAddr(r.Author)
	if !link {
		who = "this address"
	}
	kw := "n/a"
	if k := r.KeptWord(); k >= 0 {
		kw = strconv.Itoa(k) + "%"
	}
	return "| " + who + " | " + strconv.Itoa(r.Sealed) + " | " + strconv.Itoa(r.Open) + " | " +
		strconv.Itoa(r.OnTime) + " | " + strconv.Itoa(r.Late) + " | " + strconv.Itoa(r.Ducked) + " | " +
		kw + " | " + strconv.Itoa(r.Held) + " | " + strconv.Itoa(r.Missed) + " |\n"
}

// better reports whether record x ranks above y: more held calls first,
// then a higher kept-word rate, then fewer ducked calls, then more sealed.
func better(x, y Record) bool {
	if x.Held != y.Held {
		return x.Held > y.Held
	}
	if x.KeptWord() != y.KeptWord() {
		return x.KeptWord() > y.KeptWord()
	}
	if x.Ducked != y.Ducked {
		return x.Ducked < y.Ducked
	}
	return x.Sealed > y.Sealed
}

// Leaderboard returns up to n records, best first.
func Leaderboard(n int) []Record {
	now := time.Now()
	var rs []Record
	authors.Iterate("", "", func(k string, _ any) bool {
		r := recordOf(address(k), now)
		// insertion sort: the author set is small and this is a read path
		i := len(rs)
		rs = append(rs, r)
		for i > 0 && better(rs[i], rs[i-1]) {
			rs[i], rs[i-1] = rs[i-1], rs[i]
			i--
		}
		return false
	})
	if n >= 0 && len(rs) > n {
		rs = rs[:n]
	}
	return rs
}

func renderBoard(res *mux.ResponseWriter, req *mux.Request) {
	var b strings.Builder
	b.WriteString("[Receipts](" + homeLink + ") / Track records\n\n# Track records\n\n")
	b.WriteString("Ranked by calls the crowd says **held**, then **kept word** (share of due calls revealed on time), then fewest **ducked**.\n\n")
	rs := Leaderboard(50)
	if len(rs) == 0 {
		b.WriteString("_Nobody has sealed a call yet._\n")
		res.Write(b.String())
		return
	}
	b.WriteString(recordHeader)
	for _, r := range rs {
		row := recordRow(r, true)
		row = strings.Replace(row, shortAddr(r.Author), "["+shortAddr(r.Author)+"]("+homeLink+":u/"+r.Author.String()+")", 1)
		b.WriteString(row)
	}
	res.Write(b.String())
}

func renderHow(res *mux.ResponseWriter, req *mux.Request) {
	res.Write(`[Receipts](` + homeLink + `) / How it works

# How it works

1. **Write your call** and pick a random **salt** (8 to 64 characters). The salt stops anyone from guessing short calls like "yes" by brute force.
2. **Compute the commitment** off-chain: lowercase hex of ` + "`sha256(salt + \"|\" + call)`" + `. Use the [offline sealer](` + SealerURL + `) or:
   ` + "`printf '%s|%s' \"$SALT\" \"$CALL\" | sha256sum`" + `
3. **Seal** it with a public topic and a reveal deadline in days. The chain records the block height and time.
4. **Reveal** any time before the deadline by sending the exact call and salt. The realm re-hashes them and only accepts an exact match.
5. **Verdicts.** Once revealed, other accounts mark it **held** or **missed**. One verdict per account, changeable.

## Statuses

| Status | Meaning |
|---|---|
| sealed | hash public, call hidden, deadline not passed |
| revealed | opened on or before the deadline and verified |
| revealed late | opened after the deadline: verified, but it does not count as kept word |
| ducked | deadline passed, still not revealed: counts against the author |

## For developers

Read-only helpers for clients via ` + "`vm/qeval`" + `: ` + "`Commit(call, salt)`, `GetCall(id)`, `StatusOf(id)`, `TrackRecord(addr)`, `Leaderboard(n)`, `Count()`" + `. Events: ` + "`Sealed`, `Revealed`, `Verdict`" + `.
`)
}

func badge(c *Call, now time.Time) string {
	switch c.status(now) {
	case StatusSealed:
		return "🔒 sealed"
	case StatusDucked:
		return "🫥 ducked"
	case StatusLate:
		s := "⏰ revealed late"
		if o := c.outcome(); o != "" {
			s += ", " + o
		}
		return s
	}
	s := "✅ revealed"
	if o := c.outcome(); o != "" {
		s += ", " + o
	}
	return s
}

func dueIn(c *Call, now time.Time) string {
	if c.Revealed || now.After(c.RevealBy) {
		return ""
	}
	d := c.RevealBy.Sub(now)
	days := int(d.Hours()) / 24
	hours := int(d.Hours()) % 24
	return " (in " + strconv.Itoa(days) + "d " + strconv.Itoa(hours) + "h)"
}

func blocksBetween(c *Call) string {
	n := c.RevealedHeight - c.SealedHeight
	if n == 1 {
		return "1 block"
	}
	return strconv.FormatInt(n, 10) + " blocks"
}

func callLink(id int) string { return homeLink + ":call/" + strconv.Itoa(id) }

func fmtTime(t time.Time) string { return t.UTC().Format("2006-01-02 15:04 UTC") }

func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 14 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

func escDollar(s string) string { return strings.ReplaceAll(s, "$", "\\$") }

// Package arena implements the on-chain economy for Arena Ledger, a
// play-to-earn 3D shooter. Every token value is an integer count of
// millitokens (mtok): 1 token == 1000 mtok, so fractional rewards stay
// exact. All balances live in this realm's internal ledger; no external
// GRC20 package is imported.
package arena

import (
	"strconv"
	"time"

	"chain"
	"chain/banker"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

// Token amounts, in millitokens (mtok).
const (
	unitPerToken int64 = 1000 // 1 token = 1000 mtok

	entryFee    int64 = 2000 // 2.0 tokens: cost of one match
	baseBounty  int64 = 1200 // 1.2 tokens: escrowed kill bounty
	poolShare   int64 = 800  // 0.8 tokens: community-pool contribution
	boostBounty int64 = 2400 // 2.4 tokens: doubled boosted kill bounty

	startingBalance int64 = entryFee // onboarding grant: one free first entry

	faucetAmount   int64 = 10000 // 10 tokens per testnet faucet grant
	faucetCooldown int64 = 21600 // 6 hours between grants

	xpPerKill int64 = 40 // base XP for a kill
	xpPerWin  int64 = 60 // base XP for a win

	level1XP int64 = 100 // XP needed for level 1
	level2XP int64 = 300 // XP needed for level 2
	level3XP int64 = 700 // XP needed for level 3

	leaderboardSize = 10
)

// boostedHours are the three UTC hours -- 06:00, 12:00 and 18:00 -- in
// which the kill bounty doubles to 2.4 tokens. The extra 1.2 tokens come
// out of the community pool, not out of the victim's entry allocation.
var boostedHours = []int{6, 12, 18}

// multiplierPct is the XP multiplier applied to kills and wins using the
// player's level BEFORE the award: level 0 = 100% (no bonus),
// level 1 = 110%, level 2 = 120%, level 3 = 130%.
var multiplierPct = []int64{100, 110, 120, 130}

// Player is a single account in the realm's internal token ledger.
type Player struct {
	Addr    address
	Balance int64 // spendable tokens (mtok)
	Pending int64 // earned bounty not yet claimed (mtok)
	Bounty  int64 // bounty escrowed on this player from entries (mtok)
	XP      int64 // cumulative XP
	Kills   int
	Deaths  int
	Wins    int
	Entries    int
	LastFaucet int64
}

var (
	players          *avl.Tree
	pool             int64 // community pool (mtok)
	totalPlayers     int
	totalEntries     int64
	totalKills       int64
	totalBoostKills  int64
	totalDistributed int64
	backing          int64 // ugnot held to back outstanding play tokens
)

func init() {
	players = avl.NewTree()
}

// callerOf validates a realm token and returns the EOA that crossed into
// this realm. Any helper receiving a realm token must check IsCurrent;
// the exported crossing functions additionally check Previous().IsUserCall().
func callerOf(cur realm) address {
	if !cur.IsCurrent() {
		panic("invalid realm token")
	}
	return cur.Previous().Address()
}

func playerFor(a address) *Player {
	key := a.String()
	if !players.Has(key) {
		return nil
	}
	p, _ := players.Get(key).(*Player)
	return p
}

func getOrCreate(a address) *Player {
	p := playerFor(a)
	if p == nil {
		// A small onboarding grant lets a new player enter their first match.
		p = &Player{Addr: a, Balance: startingBalance}
		players.Set(a.String(), p)
		totalPlayers++
	}
	return p
}

// formatTokens renders millitokens as a decimal token string, trimming
// trailing zeros: 1200 -> "1.2", 2400 -> "2.4", 800 -> "0.8", 2000 -> "2".
// The game client prefixes this with "+" to display "+1.2" in the HUD.
func formatTokens(mtok int64) string {
	sign := ""
	if mtok < 0 {
		sign = "-"
		mtok = -mtok
	}
	whole := mtok / unitPerToken
	frac := mtok % unitPerToken
	if frac == 0 {
		return sign + strconv.FormatInt(whole, 10)
	}
	fs := strconv.FormatInt(frac, 10)
	for len(fs) < 3 {
		fs = "0" + fs
	}
	for len(fs) > 0 && fs[len(fs)-1] == '0' {
		fs = fs[:len(fs)-1]
	}
	return sign + strconv.FormatInt(whole, 10) + "." + fs
}

// entrySplit returns the bounty and community-pool parts of an entry fee.
// Their sum is exactly entryFee (1.2 + 0.8 = 2.0 tokens).
func entrySplit() (bounty, community int64) {
	return baseBounty, poolShare
}

// isBoosted reports whether t is inside one of the three boosted UTC hours.
func isBoosted(t time.Time) bool {
	h := t.UTC().Hour()
	for _, bh := range boostedHours {
		if h == bh {
			return true
		}
	}
	return false
}

// bountyForKill returns the payout and the portion funded by the community
// pool for a kill at time t. A normal kill pays 1.2 tokens entirely from
// the victim's bounty allocation. A boosted kill pays 2.4 tokens: 1.2 from
// the victim and 1.2 from the community pool.
func bountyForKill(t time.Time) (payout, fromPool int64) {
	if isBoosted(t) {
		return boostBounty, boostBounty - baseBounty
	}
	return baseBounty, 0
}

// levelForXP maps cumulative XP to a level. Players start unranked (0) and
// reach level 1 at 100 XP, level 2 at 300 XP and level 3 at 700 XP.
func levelForXP(xp int64) int {
	switch {
	case xp >= level3XP:
		return 3
	case xp >= level2XP:
		return 2
	case xp >= level1XP:
		return 1
	default:
		return 0
	}
}

// awardXP grants base XP modified by the player's current level and
// returns the amount actually awarded.
func awardXP(p *Player, base int64) int64 {
	lvl := levelForXP(p.XP)
	gained := base * multiplierPct[lvl] / 100
	p.XP += gained
	return gained
}

// Enter charges the caller 2 tokens to join a match. Of that, 1.2 tokens
// become a bounty on the entrant and 0.8 tokens go to the community pool.
func Enter(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("Enter: EOA calls only")
	}
	a := callerOf(cur)
	p := getOrCreate(a)
	if p.Balance < entryFee {
		panic("Enter: not enough balance (need 2 tokens)")
	}
	bounty, community := entrySplit()
	p.Balance -= entryFee
	p.Bounty += bounty
	pool += community
	p.Entries++
	totalEntries++
	chain.Emit("Enter", "player", a.String(), "cost", formatTokens(entryFee),
		"bounty", formatTokens(bounty), "pool", formatTokens(community))
}

// ReportKill credits the caller for killing victim. The caller is the
// killer; the victim must already have an entry bounty escrowed. During a
// boosted hour the payout is 2.4 tokens, with the extra 1.2 taken from the
// community pool. The Kill event carries the numeric "amount" (e.g. 1.2)
// so the client can display "+1.2".
func ReportKill(cur realm, victim string) {
	if !cur.Previous().IsUserCall() {
		panic("ReportKill: EOA calls only")
	}
	killerAddr := callerOf(cur)
	victimAddr := address(victim)
	if victimAddr == killerAddr {
		panic("ReportKill: cannot score a kill on yourself")
	}
	victimPlayer := playerFor(victimAddr)
	if victimPlayer == nil {
		panic("ReportKill: unknown victim")
	}
	killer := getOrCreate(killerAddr)

	payout, fromPool := bountyForKill(time.Now())
	if victimPlayer.Bounty < baseBounty {
		panic("ReportKill: victim has no bounty allocation")
	}
	if fromPool > pool {
		panic("ReportKill: community pool cannot fund the boost")
	}

	// Settle: consume the victim's base bounty, draw any boost from the pool.
	victimPlayer.Bounty -= baseBounty
	pool -= fromPool
	killer.Pending += payout
	killer.Kills++
	victimPlayer.Deaths++
	totalKills++
	totalDistributed += payout
	boosted := fromPool > 0
	if boosted {
		totalBoostKills++
	}
	gained := awardXP(killer, xpPerKill)

	chain.Emit("Kill", "killer", killerAddr.String(), "victim", victim,
		"amount", formatTokens(payout), "boosted", strconv.FormatBool(boosted),
		"xp", strconv.FormatInt(gained, 10))
	if boosted {
		chain.Emit("Boost", "killer", killerAddr.String(),
			"amount", formatTokens(payout), "hour", strconv.Itoa(time.Now().UTC().Hour()))
	}
}

// ReportWin records a match win for the caller. Wins grant XP (with the
// caller's level multiplier) but do not move tokens.
func ReportWin(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("ReportWin: EOA calls only")
	}
	a := callerOf(cur)
	p := getOrCreate(a)
	p.Wins++
	gained := awardXP(p, xpPerWin)
	chain.Emit("Win", "player", a.String(), "xp", strconv.FormatInt(gained, 10))
}

// canFaucet enforces the testnet grant cooldown. A zero timestamp means
// the player has never taken a grant.
func canFaucet(last, now int64) bool {
	return last == 0 || now-last >= faucetCooldown
}

// Faucet grants testnet tokens so players can keep entering matches after
// their one-token onboarding balance is spent. This is a testnet-only
// convenience; a production realm would use a real token sale or bridge.
func Faucet(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("Faucet: EOA calls only")
	}
	a := callerOf(cur)
	p := getOrCreate(a)
	now := time.Now().Unix()
	if !canFaucet(p.LastFaucet, now) {
		panic("Faucet: wait before the next grant")
	}
	p.Balance += faucetAmount
	p.LastFaucet = now
	chain.Emit("Faucet", "player", a.String(), "amount", formatTokens(faucetAmount),
		"amount_mtok", strconv.FormatInt(faucetAmount, 10))
}

// Buy swaps attached GNOT for play tokens at 1 ugnot = 1 millitoken.
// The received coins stay at the realm address as backing for withdrawals.
func Buy(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("Buy: EOA calls only")
	}
	coins := unsafe.OriginSend()
	if len(coins) != 1 || coins[0].Denom != "ugnot" || coins[0].Amount <= 0 {
		panic("Buy: send ugnot to buy tokens")
	}
	a := callerOf(cur)
	p := getOrCreate(a)
	p.Balance += coins[0].Amount
	backing += coins[0].Amount
	chain.Emit("Buy", "player", a.String(), "ugnot", strconv.FormatInt(coins[0].Amount, 10),
		"tokens", formatTokens(coins[0].Amount))
}

// canWithdraw verifies both the internal credit and the realm's GNOT backing.
func canWithdraw(balance, available, mtok int64) bool {
	return mtok > 0 && mtok <= balance && mtok <= available
}

// Withdraw burns play tokens and sends the equivalent ugnot from the realm.
func Withdraw(cur realm, mtok int64) {
	if !cur.Previous().IsUserCall() {
		panic("Withdraw: EOA calls only")
	}
	a := callerOf(cur)
	p := playerFor(a)
	if p == nil || !canWithdraw(p.Balance, backing, mtok) {
		panic("Withdraw: not enough credit or backing")
	}
	p.Balance -= mtok
	backing -= mtok
	b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	b.SendCoins(cur.Address(), a, chain.Coins{{Denom: "ugnot", Amount: mtok}})
	chain.Emit("Withdraw", "player", a.String(), "amount_mtok", strconv.FormatInt(mtok, 10))
}

// Claim moves the caller's pending kill rewards into their spendable
// balance so they can pay for another entry.
func Claim(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("Claim: EOA calls only")
	}
	a := callerOf(cur)
	p := playerFor(a)
	if p == nil {
		panic("Claim: no player record")
	}
	amount := p.Pending
	if amount <= 0 {
		panic("Claim: nothing to claim")
	}
	p.Pending = 0
	p.Balance += amount
	chain.Emit("Claim", "player", a.String(), "amount", formatTokens(amount),
		"amount_mtok", strconv.FormatInt(amount, 10))
}

// better ranks a above b by XP, then kills, then wins, then address.
// It is the strict ordering used to build the leaderboard.
func better(a, b *Player) bool {
	if a.XP != b.XP {
		return a.XP > b.XP
	}
	if a.Kills != b.Kills {
		return a.Kills > b.Kills
	}
	if a.Wins != b.Wins {
		return a.Wins > b.Wins
	}
	return a.Addr.String() < b.Addr.String()
}

// Top returns the ten highest-ranked players according to better.
func Top() []*Player {
	list := []*Player{}
	players.Iterate("", "", func(key string, value any) bool {
		if p, ok := value.(*Player); ok {
			list = append(list, p)
		}
		return false
	})
	for i := 1; i < len(list); i++ {
		j := i
		for j > 0 && better(list[j], list[j-1]) {
			list[j], list[j-1] = list[j-1], list[j]
			j--
		}
	}
	if len(list) > leaderboardSize {
		return list[:leaderboardSize]
	}
	return list
}

