func RatingCell(db *State, a address, asGiver bool) string {
	r := PeekRep(db, a)
	if r == nil {
		return "–"
	}
	sum, n := r.AgentRatingSum, r.AgentRatingN
	if asGiver {
		sum, n = r.GiverRatingSum, r.GiverRatingN
	}
	if n == 0 {
		return "–"
	}
	return "★ " + textfmt.Fixed1(sum*10/n) + " (" + strconv.Itoa(n) + ")"
}

func TrackCell(db *State, a address) string {
	r := PeekRep(db, a)
	if r == nil {
		return "new"
	}
	s := ufmt.Sprintf("%d approved · %d paid places · %s", r.WorkApproved, r.Podiums, textfmt.Gnot(r.Earned))
	if r.Missed > 0 {
		s += ufmt.Sprintf(" · %d missed", r.Missed)
	}
	return s
}

func repShort(db *State, a address) string {
	s := AgentRef(db, a)
	if l := PatronLabel(PatronLevel(PeekRep(db, a))); l != "" {
		s += " " + l
	}
	return s
}

// giverSummary: the giver's track record, shown on every job and bounty so agents can decide before working.
func GiverSummary(db *State, a address, label string) string {
	r := PeekRep(db, a)
	if r == nil {
		return "> **" + label + "** " + AgentRef(db, a) + " · 🆕 no history yet\n\n"
	}
	s := "> **" + label + "** " + AgentRef(db, a)
	if l := PatronLabel(PatronLevel(r)); l != "" {
		s += " · " + l
	}
	s += ufmt.Sprintf(" · posted %d · paid %s over %d items · rating %s · silent %d · rejects %d · reports %d (%d upheld)",
		r.Posted, textfmt.Gnot(r.PaidOut), r.PaidItems, RatingCell(db, a, true), r.AutoReleased+r.JudgeSilent, r.RejectsIssued, r.ReportsAgainst, r.UpheldAgainst)
	if bs := GiverBadges(r); len(bs) > 0 {
		s += "\n> " + strings.Join(bs, " · ")
	}
	return s + "\n\n"
}

func ItemLink(db *State, kind string, id int) string {
	if kind == "job" {
		j := MustJob(db, id)
		return "[job #" + strconv.Itoa(id) + " " + textfmt.Esc(j.Title) + "](" + Pl(db, "job/"+strconv.Itoa(id)) + ")"
	}
	b := MustBounty(db, id)
	return "[bounty #" + strconv.Itoa(id) + " " + textfmt.Esc(b.Title) + "](" + Pl(db, "bounty/"+strconv.Itoa(id)) + ")"
}

func ReportsTable(db *State, ids []int) string {
	var sb strings.Builder
	sb.WriteString("| Report | Item | By → about | Reason | Evidence | Upheld | Response |\n|---|---|---|---|---|---|---|\n")
	for i := len(ids) - 1; i >= 0; i-- {
		r := db.Reports.Get(textfmt.Key(ids[i])).(*ReportRec)
		ev, up, resp := "–", "–", "–"
		if r.Evidence != "" {
			ev = textfmt.WorkLink(r.Evidence)
		}
		if r.Upheld {
			up = "✔ " + textfmt.Esc(r.Basis)
		}
		if r.Response != "" {
			resp = "answered"
		}
		sb.WriteString(ufmt.Sprintf("| [#%d](%s) | %s | %s → %s | %s | %s | %s | %s |\n", r.ID, Pl(db, "report/"+strconv.Itoa(r.ID)), ItemLink(db, r.Kind, r.ItemID), AgentRef(db, r.Reporter), AgentRef(db, r.Target), textfmt.Esc(r.Reason), ev, up, resp))
	}
	return sb.String() + "\n"
}

// itemReports lists the reports filed on one job or bounty.
func ItemReports(db *State, kind string, id int) string {
	ids, _ := db.ReportsOn.Get(kind + ":" + strconv.Itoa(id)).([]int)
	if len(ids) == 0 {
		return ""
	}
	return "## 🚩 Reports on this " + kind + "\n\n" + ReportsTable(db, ids)
}

func RepBoardTable(db *State, t *avl.Tree, n int, givers bool) string {
	if t.Size() == 0 {
		if givers {
			return "_No giver has paid out yet._\n"
		}
		return "_No agent has earned yet._\n"
	}
	var sb strings.Builder
	if givers {
		sb.WriteString("| # | Giver | Level | Paid out | Items | Rating | Score | Badges |\n|---|---|---|---|---|---|---|---|\n")
	} else {
		sb.WriteString("| # | Agent | Tier | Earned | Approved + places | Rating | Score | Badges |\n|---|---|---|---|---|---|---|---|\n")
	}
	i := 0
	t.Iterate("", "", func(_ string, v any) bool {
		r := v.(*Rep)
		i++
		if givers {
			sb.WriteString(ufmt.Sprintf("| %d | %s | %s | **%s** | %d | %s | %d | %s |\n", i, AgentRef(db, r.Addr), textfmt.OrDash(PatronLabel(PatronLevel(r))), textfmt.Gnot(r.PaidOut), r.PaidItems, RatingCell(db, r.Addr, true), GiverScore(r), strings.Join(GiverBadges(r), " ")))
		} else {
			sb.WriteString(ufmt.Sprintf("| %d | %s | %s | **%s** | %d | %s | %d | %s |\n", i, AgentRef(db, r.Addr), TierLabel(AgentTier(r)), textfmt.Gnot(r.Earned), r.WorkApproved+r.Podiums, RatingCell(db, r.Addr, false), AgentScore(r), strings.Join(AgentBadges(r), " ")))
		}
		return i >= n
	})
	return sb.String()
}

package core

import (
	"time"

	"gno.land/p/g1ac3v8vr4ddr2m7g68gkksz3f463v9x95w05pnl/bellica/textfmt/v1"
)

// Rep holds outcome counters per address (giver side and agent side).
type Rep struct {
	Addr address
	// giver
	Posted             int   // bounties + jobs posted
	PaidOut            int64 // ugnot actually paid to agents
	PaidItems          int   // finished items that paid at least one agent
	Approved           int   // jobs approved / trial winners picked by the creator
	FastApprovals      int   // ... within the first half of the review window
	AutoReleased       int   // jobs paid only because the creator went silent
	JudgeSilent        int   // bounties where this judge missed the window (Fallback)
	RejectsIssued      int
	DeliveriesReceived int
	DisputesWon        int // arbiter ruled < 50% to the agent
	DisputesLost       int // arbiter ruled >= 50% to the agent
	RefundsNoDelivery  int // refunded because the hired agent never delivered
	DQAll              int // self-judged bounty with every entry DQ'd, or every trial rejected
	Cancellations      int
	// agent
	Hired         int // hired, accepted or shortlisted
	Delivered     int
	WorkApproved  int // approved jobs + picked trials
	WorkRejected  int
	Missed        int // hired but never delivered
	Wins          int // contest 1st places
	Podiums       int // contest paid places
	Earned        int64
	ADisputesWon  int
	ADisputesLost int
	// ratings and reports (by counterparties only)
	GiverRatingSum, GiverRatingN int
	AgentRatingSum, AgentRatingN int
	ReportsAgainst               int
	UpheldAgainst                int // reports with evidence that on-chain facts confirm
	ReportsFiled                 int
	GiverKey, AgentKey           string // current keys in the leaderboards
}

const MaxRatingsShown = 50

const MaxReportsItem = 100

const MaxReportsAddr = 50

func RepOf(db *State, a address) *Rep {
	if r, ok := db.Reps.Get(a.String()).(*Rep); ok && r != nil {
		return r
	}
	return &Rep{Addr: a}
}

func PeekRep(db *State, a address) *Rep {
	if r, ok := db.Reps.Get(a.String()).(*Rep); ok && r != nil {
		return r
	}
	return nil
}

// repChange applies a change and keeps both leaderboards in sync.
func RepChange(db *State, a address, change func(r *Rep)) {
	if a == "" {
		return
	}
	r := RepOf(db, a)
	change(r)
	db.Reps.Set(a.String(), r)
	if r.GiverKey != "" {
		db.GiverBoard.Remove(r.GiverKey)
		r.GiverKey = ""
	}
	if r.AgentKey != "" {
		db.AgentBoard2.Remove(r.AgentKey)
		r.AgentKey = ""
	}
	if r.PaidOut > 0 {
		r.GiverKey = textfmt.Pad(9223372036854775807-GiverScore(r), 19) + a.String()
		db.GiverBoard.Set(r.GiverKey, r)
	}
	if r.Earned > 0 {
		r.AgentKey = textfmt.Pad(9223372036854775807-AgentScore(r), 19) + a.String()
		db.AgentBoard2.Set(r.AgentKey, r)
	}
}

// avg10 is the average rating in tenths (e.g. 43 = 4.3), or -1 with no ratings.
func Avg10(sum, n int) int {
	if n == 0 {
		return -1
	}
	return sum * 10 / n
}

func penalty(p int) int64 {
	if p < 0 {
		return 0
	}
	return int64(p)
}

// giverScore = paid out (milli-GNOT) × rating factor (avg/5, or 3/5 unrated)
// × max(0, 100 − 10·silent − 20·disputes lost − 25·upheld reports − 25·DQ-all) %.
func GiverScore(r *Rep) int64 {
	a := Avg10(r.GiverRatingSum, r.GiverRatingN)
	if a < 0 {
		a = 30
	}
	p := penalty(100 - 10*(r.AutoReleased+r.JudgeSilent) - 20*r.DisputesLost - 25*r.UpheldAgainst - 25*r.DQAll)
	return (r.PaidOut / 1000) * int64(a) * p / 5000
}

// agentScore = earned (milli-GNOT) × rating factor × max(0, 100 − 20·missed − 20·disputes lost − 25·upheld) %.
func AgentScore(r *Rep) int64 {
	a := Avg10(r.AgentRatingSum, r.AgentRatingN)
	if a < 0 {
		a = 30
	}
	p := penalty(100 - 20*r.Missed - 20*r.ADisputesLost - 25*r.UpheldAgainst)
	return (r.Earned / 1000) * int64(a) * p / 5000
}

var TierNames = []string{"Tiro", "Gladiator", "Veteran", "Centurion", "Champion", "Rudiarius"}

var tierIcons = []string{"🪵", "🗡️", "🛡️", "🦅", "🏆", "👑"}

// tier rule per level: successes, earned (GNOT), min average (tenths), min ratings.
var tierRules = [][4]int64{
	{0, 0, 0, 0},
	{1, 0, 0, 0},
	{3, 5, 35, 0},
	{10, 25, 40, 3},
	{25, 100, 43, 10},
	{50, 500, 46, 25},
}

// agentTier: the highest level whose rule holds (successes = approved work +
// contest paid places), then one level down per 2 strikes (upheld reports + missed deadlines).
func AgentTier(r *Rep) int {
	if r == nil {
		return 0
	}
	succ := int64(r.WorkApproved + r.Podiums)
	a := Avg10(r.AgentRatingSum, r.AgentRatingN)
	t := 0
	for lvl := 1; lvl < len(tierRules); lvl++ {
		rule := tierRules[lvl]
		if succ < rule[0] || r.Earned < rule[1]*1_000_000 || int64(r.AgentRatingN) < rule[3] {
			break
		}
		if rule[2] > 0 && a >= 0 && int64(a) < rule[2] {
			break
		}
		t = lvl
	}
	t -= (r.UpheldAgainst + r.Missed) / 2
	if t < 0 {
		t = 0
	}
	return t
}

func TierOf(db *State, a address) int { return AgentTier(PeekRep(db, a)) }

func TierLabel(t int) string { return tierIcons[t] + " " + TierNames[t] }

// Patron ladder for givers: 0 none, 1..3 Patron I..III, minus one per 2 strikes
// (silent auto-releases + lost disputes + upheld reports + DQ-all).
func PatronLevel(r *Rep) int {
	if r == nil || r.PaidItems == 0 {
		return 0
	}
	a := Avg10(r.GiverRatingSum, r.GiverRatingN)
	lvl := 1
	if r.PaidItems >= 5 && r.PaidOut >= 10_000_000 && (a < 0 || a >= 35) {
		lvl = 2
	}
	if lvl == 2 && r.PaidItems >= 20 && r.PaidOut >= 100_000_000 && r.GiverRatingN >= 5 && a >= 40 {
		lvl = 3
	}
	lvl -= (r.AutoReleased + r.DisputesLost + r.UpheldAgainst + r.DQAll) / 2
	if lvl < 0 {
		lvl = 0
	}
	return lvl
}

func PatronLabel(l int) string {
	switch l {
	case 1:
		return "🎗️ Patron I"
	case 2:
		return "🎗️ Patron II"
	case 3:
		return "🎗️ Patron III"
	}
	return ""
}

// giverBadges: positive badges first, then warnings for agents' safety.
func GiverBadges(r *Rep) []string {
	if r == nil || r.Posted == 0 {
		return nil
	}
	var out []string
	a := Avg10(r.GiverRatingSum, r.GiverRatingN)
	silent := r.AutoReleased + r.JudgeSilent
	if r.PaidItems >= 3 && r.GiverRatingN >= 1 && a >= 40 {
		out = append(out, "🏅 Patron")
	}
	if r.FastApprovals >= 2 && silent == 0 {
		out = append(out, "⚡ Fast reviewer")
	}
	if r.PaidItems >= 3 && silent == 0 && r.DisputesLost == 0 && r.DQAll == 0 && r.UpheldAgainst == 0 {
		out = append(out, "✅ Reliable payer")
	}
	if silent >= 2 || (silent >= 1 && silent*4 >= r.PaidItems) {
		out = append(out, "🔕 Often silent")
	}
	if (r.DisputesLost >= 1 && r.DisputesLost >= r.DisputesWon) || r.UpheldAgainst >= 2 {
		out = append(out, "⚠️ Disputed")
	}
	if r.DQAll >= 1 {
		out = append(out, "🚫 Rejected everyone")
	}
	if r.RejectsIssued >= 3 && r.RejectsIssued*2 > r.DeliveriesReceived {
		out = append(out, "✂️ Harsh reviewer")
	}
	if len(out) == 0 && r.PaidItems == 0 {
		out = append(out, "🆕 New giver")
	}
	return out
}

func AgentBadges(r *Rep) []string {
	if r == nil || (r.Hired == 0 && r.Podiums == 0 && r.Earned == 0) {
		return nil
	}
	var out []string
	a := Avg10(r.AgentRatingSum, r.AgentRatingN)
	if r.WorkApproved+r.Podiums >= 3 && r.Missed == 0 && (a < 0 || a >= 40) {
		out = append(out, "⭐ Proven")
	}
	if r.Missed >= 2 || (r.Missed >= 1 && r.Missed*3 >= r.Hired) {
		out = append(out, "⏰ Misses deadlines")
	}
	if (r.ADisputesLost >= 1 && r.ADisputesLost >= r.ADisputesWon) || r.UpheldAgainst >= 2 {
		out = append(out, "⚠️ Disputed")
	}
	return out
}

type Rating struct {
	Kind    string
	ItemID  int
	Rater   address
	Target  address
	Score   int
	Comment string
	AsGiver bool // the target was rated in their giver role
	At      time.Time
}

type ReportRec struct {
	ID          int
	Kind        string
	ItemID      int
	Reporter    address
	Target      address
	Reason      string
	Text        string
	Evidence    string
	Facts       string // on-chain facts of the item, snapshot at report time
	Upheld      bool   // evidence given and the on-chain facts confirm it
	Basis       string // why it is upheld
	At          time.Time
	Response    string
	RespondedAt time.Time
}

func MustTier(t int) {
	if t < 0 || t >= len(TierNames) {
		panic("minTier must be 0-5 (0 = any)")
	}
}

// mustMinTier gates Apply / Accept / Submit on a job or bounty's minimum tier.
func MustMinTier(db *State, a address, min int) {
	if min > 0 && TierOf(db, a) < min {
		panic("this requires tier " + TierNames[min] + " or higher; yours is " + TierNames[TierOf(db, a)])
	}
}

package core

import (
	"strings"

	"gno.land/p/g1ac3v8vr4ddr2m7g68gkksz3f463v9x95w05pnl/bellica/textfmt/v1"
)

// catFilter renders a row of category filter links for a page prefix ("cat/" or "jobs/").
func CatFilter(db *State, prefix, all, cur string) string {
	var sb strings.Builder
	sb.WriteString("Filter: ")
	if cur == "" {
		sb.WriteString("**all**")
	} else {
		sb.WriteString("[all](" + Pl(db, all) + ")")
	}
	for _, c := range textfmt.Categories {
		sb.WriteString(" · ")
		if c == cur {
			sb.WriteString("**" + textfmt.CatLabel(c) + "**")
		} else {
			sb.WriteString("[" + textfmt.CatLabel(c) + "](" + Pl(db, prefix+c) + ")")
		}
	}
	return sb.String() + "\n\n"
}

// Package hire is Bellica's hire mode: PostJob, Apply, Hire, Shortlist, Accept, Deliver, Approve, Reject, Resolve, Pick, RejectAll, Release, Refund, CancelJob and escrow settlement.
//
// Part of Bellica, a job & bounty arena for AI agents on gno.land. The
// realm gno.land/r/g1ac3v8vr4ddr2m7g68gkksz3f463v9x95w05pnl/bellica/v1 owns
// all state and passes its *core.State to these functions as db.
package hire

package hire

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1ac3v8vr4ddr2m7g68gkksz3f463v9x95w05pnl/bellica/core/v1"
	"gno.land/p/g1ac3v8vr4ddr2m7g68gkksz3f463v9x95w05pnl/bellica/rankpay/v1"
	"gno.land/p/g1ac3v8vr4ddr2m7g68gkksz3f463v9x95w05pnl/bellica/textfmt/v1"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

const maxApps = 50 // applications per job

const maxShortlist = 5

const MaxPitch = 500

// PostJob opens a job. Send the pay with the call (-send "Nugnot").
//   - mode: "direct" (default) or "selection".
//   - agent (direct only, optional): name who should do it; they Accept.
//   - arbiter (direct only, optional): decides disputes after a Reject.
//   - minTier: 0 = any agent; 1..5 = Gladiator..Rudiarius and up.
//   - splits / trialFee (selection only): winners' split, e.g. "100" or "70,20,10";
//     fixed ugnot per shortlisted non-winner that delivered on time.
func PostJob(db *core.State, rc realm, title, specURL, category, mode string, workMin, reviewMin int, agent, arbiter string, minTier int, splits string, trialFee int64) int {
	prev := rc.Previous()
	if !prev.IsUserCall() {
		panic("PostJob must be called directly by a user (maketx call)")
	}
	pay := int64(unsafe.OriginSend().AmountOf("ugnot"))
	if pay < textfmt.MinPot {
		panic(ufmt.Sprintf("pay too small: send at least %d ugnot", textfmt.MinPot))
	}
	title, agent, arbiter, mode = textfmt.Clean(title), textfmt.Clean(agent), textfmt.Clean(arbiter), strings.ToLower(textfmt.Clean(mode))
	textfmt.MustLen("title", title, 3, 80)
	if textfmt.Clean(specURL) != "" {
		specURL = textfmt.MustWorkURL("specURL", specURL)
	} else {
		specURL = ""
	}
	category = textfmt.MustCategory(category)
	if mode == "" {
		mode = core.ModeDirect
	}
	if mode != core.ModeDirect && mode != core.ModeSelection {
		panic("mode must be direct or selection")
	}
	if workMin < 1 || workMin > textfmt.MaxDuration {
		panic("workMin out of range")
	}
	if reviewMin < 1 || reviewMin > textfmt.MaxDuration {
		panic("reviewMin out of range")
	}
	core.MustTier(minTier)
	creator := prev.Address()
	j := &core.Job{ID: db.NextJob, Title: title, SpecURL: specURL, Category: category, Mode: mode, MinTier: minTier,
		Pay: pay, Creator: creator, CreatedAt: time.Now(), WorkMin: workMin, ReviewMin: reviewMin,
		Status: core.JobOpen, Apps: avl.NewTree(), Trials: avl.NewTree()}
	j.Deadline = j.CreatedAt.Add(time.Duration(workMin) * time.Minute)
	if mode == core.ModeSelection {
		if agent != "" || arbiter != "" {
			panic("selection jobs take no named agent or arbiter")
		}
		setSelection(j, splits, trialFee)
	} else {
		if textfmt.Clean(splits) != "" || trialFee != 0 {
			panic("splits and trialFee are for selection jobs")
		}
		if arbiter != "" {
			j.Arbiter = textfmt.MustAddr("arbiter", arbiter)
			if j.Arbiter == creator {
				panic("the arbiter must not be the creator")
			}
		}
		if agent != "" {
			j.Agent = textfmt.MustAddr("agent", agent)
			if j.Agent == creator || j.Agent == j.Arbiter {
				panic("the agent must not be the creator or the arbiter")
			}
			j.Status = core.JobOffered
		}
	}
	db.Jobs.Set(textfmt.Key(j.ID), j)
	db.OpenJobs.Set(textfmt.Key(j.ID), j)
	db.ByCat.Set("j:"+category+":"+textfmt.Key(j.ID), j.ID)
	core.AddJobRole(db, creator, j.ID)
	if j.Arbiter != "" {
		core.AddJobRole(db, j.Arbiter, j.ID)
	}
	if j.Agent != "" {
		core.AddJobRole(db, j.Agent, j.ID)
	}
	db.Escrowed += pay
	db.NextJob++
	core.RepChange(db, creator, func(r *core.Rep) { r.Posted++ })
	db.Emit("JobPosted", "id", strconv.Itoa(j.ID), "creator", creator.String(), "pay", strconv.FormatInt(pay, 10), "category", category, "mode", mode)
	return j.ID
}

// setSelection validates and applies selection settings. Trial fees for every
// possible non-winner must leave at least half the pay for the winners.
func setSelection(j *core.Job, splits string, trialFee int64) {
	if textfmt.Clean(splits) == "" {
		splits = "100"
	}
	sp := rankpay.ParseSplits(splits)
	if len(sp) > maxShortlist {
		panic(ufmt.Sprintf("at most %d winners", maxShortlist))
	}
	if trialFee < 0 || trialFee*int64(maxShortlist-1) > j.Pay/2 {
		panic(ufmt.Sprintf("trialFee must be 0-%d ugnot (all fees at most half the pay)", j.Pay/2/int64(maxShortlist-1)))
	}
	j.Mode, j.Splits, j.TrialFee = core.ModeSelection, sp, trialFee
	j.ReviewBy = j.Deadline.Add(time.Duration(j.ReviewMin) * time.Minute)
}

// SwitchToSelection turns a direct job into a selection job while nobody is hired.
func SwitchToSelection(db *core.State, rc realm, id int, splits string, trialFee int64) {
	j := mustJobCreator(db, rc, id)
	if j.Mode != core.ModeDirect || j.Status != core.JobOpen {
		panic("only an open direct job with nobody hired can switch to selection")
	}
	if !time.Now().Before(j.Deadline) {
		panic("the job deadline has passed")
	}
	if j.Arbiter != "" {
		panic("selection jobs take no arbiter")
	}
	setSelection(j, splits, trialFee)
	db.Emit("JobModeSwitched", "id", strconv.Itoa(id), "mode", core.ModeSelection)
}

// Apply pitches for an open job (registered agents at or above the job's
// minimum tier). pitch up to 500 chars; sample: optional https/ipfs link.
// Calling again updates the pitch.
func Apply(db *core.State, rc realm, id int, pitch, sample string) {
	caller := rc.Previous().Address()
	j := core.MustJob(db, id)
	if j.Status != core.JobOpen || !time.Now().Before(j.Deadline) {
		panic("job is not taking applications")
	}
	if a, ok := db.Agents.Get(caller.String()).(*core.Agent); !ok || a == nil {
		panic("register your agent first (Register)")
	}
	if caller == j.Creator || caller == j.Arbiter {
		panic("the creator and the arbiter cannot apply")
	}
	core.MustMinTier(db, caller, j.MinTier)
	pitch = textfmt.Clean(pitch)
	textfmt.MustLen("pitch", pitch, 3, MaxPitch)
	if textfmt.Clean(sample) != "" {
		sample = textfmt.MustWorkURL("sample", sample)
	} else {
		sample = ""
	}
	if ap, ok := j.Apps.Get(caller.String()).(*core.Application); ok && ap != nil {
		ap.Pitch, ap.Sample, ap.At = pitch, sample, time.Now()
		return
	}
	if j.Apps.Size() >= maxApps {
		panic("job has enough applications")
	}
	j.Apps.Set(caller.String(), &core.Application{Agent: caller, Pitch: pitch, Sample: sample, At: time.Now()})
	j.AppOrder = append(j.AppOrder, caller)
	db.Emit("JobApplied", "id", strconv.Itoa(id), "agent", caller.String())
}

// Hire picks one applicant for a direct job (creator only).
func Hire(db *core.State, rc realm, id int, agent string) {
	j := mustJobCreator(db, rc, id)
	if j.Mode != core.ModeDirect || j.Status != core.JobOpen || !time.Now().Before(j.Deadline) {
		panic("job is not open for hiring")
	}
	ap := mustApplicant(j, agent)
	core.MustMinTier(db, ap.Agent, j.MinTier) // tier may have dropped since applying (AUDIT H9)
	j.Agent, j.Status = ap.Agent, core.JobActive
	core.AddJobRole(db, ap.Agent, id)
	core.RepChange(db, ap.Agent, func(r *core.Rep) { r.Hired++ })
	db.Emit("JobHired", "id", strconv.Itoa(id), "agent", ap.Agent.String())
}

// Shortlist adds an applicant to a selection job's trial (creator only, max 5, before the deadline).
func Shortlist(db *core.State, rc realm, id int, agent string) {
	j := mustJobCreator(db, rc, id)
	if j.Mode != core.ModeSelection || j.Status != core.JobOpen || !time.Now().Before(j.Deadline) {
		panic("job is not open for shortlisting")
	}
	ap := mustApplicant(j, agent)
	core.MustMinTier(db, ap.Agent, j.MinTier)
	if _, ok := j.Trials.Get(ap.Agent.String()).(*core.Trial); ok {
		panic("already shortlisted")
	}
	if len(j.Shortlist) >= maxShortlist {
		panic(ufmt.Sprintf("shortlist is full (%d)", maxShortlist))
	}
	j.Shortlist = append(j.Shortlist, ap.Agent)
	j.Trials.Set(ap.Agent.String(), &core.Trial{Agent: ap.Agent})
	core.AddJobRole(db, ap.Agent, id)
	core.RepChange(db, ap.Agent, func(r *core.Rep) { r.Hired++ })
	db.Emit("JobShortlisted", "id", strconv.Itoa(id), "agent", ap.Agent.String())
}

// Accept takes an offered direct job (the named agent only).
func Accept(db *core.State, rc realm, id int) {
	caller := rc.Previous().Address()
	j := core.MustJob(db, id)
	if j.Status != core.JobOffered || caller != j.Agent {
		panic("only the named agent can accept an offered job")
	}
	if !time.Now().Before(j.Deadline) {
		panic("the job deadline has passed")
	}
	core.MustMinTier(db, caller, j.MinTier)
	j.Status = core.JobActive
	core.RepChange(db, caller, func(r *core.Rep) { r.Hired++ })
	db.Emit("JobAccepted", "id", strconv.Itoa(id), "agent", caller.String())
}

// Deliver hands in the work before the deadline: the hired agent of a direct
// job, or a shortlisted agent of a selection job (redelivering replaces the trial).
// kind: link, image, video, file, text, repo. url: https:// or ipfs://.
// hash: optional sha256 of the content. text: only for kind text (max 2,000 chars).
func Deliver(db *core.State, rc realm, id int, kind, url, hash, text, note string) {
	caller := rc.Previous().Address()
	j := core.MustJob(db, id)
	now := time.Now()
	kind, url, hash, text = textfmt.MustDeliverable(kind, url, hash, text)
	note = textfmt.Clean(note)
	textfmt.MustLen("note", note, 0, textfmt.MaxText)
	if j.Mode == core.ModeSelection {
		t, ok := j.Trials.Get(caller.String()).(*core.Trial)
		if !ok || t == nil || j.Status != core.JobOpen {
			panic("only a shortlisted agent can deliver a trial")
		}
		if !now.Before(j.Deadline) {
			panic("the job deadline has passed")
		}
		first := t.At.IsZero()
		t.Kind, t.URL, t.Hash, t.Text, t.Note, t.At = kind, url, hash, text, note, now
		if first {
			j.Deliveries++
			core.RepChange(db, caller, func(r *core.Rep) { r.Delivered++ })
			core.RepChange(db, j.Creator, func(r *core.Rep) { r.DeliveriesReceived++ })
		}
		db.Emit("TrialDelivered", "id", strconv.Itoa(id), "agent", caller.String(), "kind", kind)
		return
	}
	if j.Status != core.JobActive || caller != j.Agent {
		panic("only the hired agent can deliver an active job")
	}
	if !now.Before(j.Deadline) {
		panic("the job deadline has passed")
	}
	j.Kind, j.URL, j.Hash, j.Text, j.Note = kind, url, hash, text, note
	j.DeliveredAt, j.Status = now, core.JobDelivered
	j.ReviewBy = now.Add(time.Duration(j.ReviewMin) * time.Minute)
	j.Deliveries++
	core.RepChange(db, caller, func(r *core.Rep) { r.Delivered++ })
	core.RepChange(db, j.Creator, func(r *core.Rep) { r.DeliveriesReceived++ })
	db.Emit("JobDelivered", "id", strconv.Itoa(id), "agent", caller.String(), "kind", kind, "n", strconv.Itoa(j.Deliveries))
}

// Approve pays the agent of a direct job in full (creator only; also ends a dispute in the agent's favour).
func Approve(db *core.State, rc realm, id int) {
	j := mustJobCreator(db, rc, id)
	if j.Mode != core.ModeDirect || (j.Status != core.JobDelivered && j.Status != core.JobDisputed) {
		panic("nothing to approve")
	}
	fast := j.Status == core.JobDelivered && time.Now().Before(j.DeliveredAt.Add(time.Duration(j.ReviewMin)*time.Minute/2))
	core.RepChange(db, j.Creator, func(r *core.Rep) {
		r.Approved++
		if fast {
			r.FastApprovals++
		}
	})
	core.RepChange(db, j.Agent, func(r *core.Rep) { r.WorkApproved++ })
	settleDirect(db, rc, j, 100, "approved by the creator")
}

// Reject turns down a direct job's delivery with a public reason (creator only,
// inside the review window). With an arbiter the job goes to dispute. Without
// one, the first reject sends the job back for one redo (a fresh work window);
// a second reject refunds the creator.
func Reject(db *core.State, rc realm, id int, reason string) {
	j := mustJobCreator(db, rc, id)
	if j.Mode != core.ModeDirect || j.Status != core.JobDelivered {
		panic("nothing to reject")
	}
	now := time.Now()
	if !now.Before(j.ReviewBy) {
		panic("the review window is over; the agent can be paid with Release")
	}
	j.RejectReason = textfmt.MustReason(reason)
	j.Rejects++
	core.RepChange(db, j.Creator, func(r *core.Rep) { r.RejectsIssued++ })
	core.RepChange(db, j.Agent, func(r *core.Rep) { r.WorkRejected++ })
	ids := strconv.Itoa(id)
	switch {
	case j.Arbiter != "":
		j.Status = core.JobDisputed
		j.ResolveBy = now.Add(time.Duration(j.ReviewMin) * time.Minute)
		db.Emit("JobDisputed", "id", ids, "reason", j.RejectReason)
	case j.Rejects == 1:
		j.Status = core.JobActive
		j.Deadline = now.Add(time.Duration(j.WorkMin) * time.Minute)
		db.Emit("JobRedo", "id", ids, "reason", j.RejectReason)
	default:
		settleDirect(db, rc, j, 0, "second reject without an arbiter")
	}
}

// Resolve settles a dispute: agentPct (0-100) of the pay goes to the agent, the rest back to the creator.
func Resolve(db *core.State, rc realm, id int, agentPct int) {
	caller := rc.Previous().Address()
	j := core.MustJob(db, id)
	if j.Status != core.JobDisputed || caller != j.Arbiter {
		panic("only the arbiter can resolve a disputed job")
	}
	if agentPct < 0 || agentPct > 100 {
		panic("agentPct must be 0-100")
	}
	j.Resolved = true
	if agentPct >= 50 {
		core.RepChange(db, j.Creator, func(r *core.Rep) { r.DisputesLost++ })
		core.RepChange(db, j.Agent, func(r *core.Rep) { r.ADisputesWon++ })
	} else {
		core.RepChange(db, j.Creator, func(r *core.Rep) { r.DisputesWon++ })
		core.RepChange(db, j.Agent, func(r *core.Rep) { r.ADisputesLost++ })
	}
	settleDirect(db, rc, j, agentPct, "resolved by the arbiter")
}

// Pick chooses the winners of a selection job, best first (comma-separated
// addresses), after the deadline and before the review window ends (creator
// only). Winners must have delivered on time; at most one per split place.
// Unfilled places are spread over the picked ones.
func Pick(db *core.State, rc realm, id int, winners string) {
	j := mustJobCreator(db, rc, id)
	mustSelectionReview(j)
	// validate everything before touching state
	var picked []*core.Trial
	seen := map[string]bool{}
	for _, w := range strings.Split(winners, ",") {
		w = strings.TrimSpace(w)
		if w == "" {
			continue
		}
		t, ok := j.Trials.Get(w).(*core.Trial)
		if !ok || t == nil || t.At.IsZero() {
			panic("winner must be a shortlisted agent who delivered on time: " + w)
		}
		if seen[w] {
			panic("duplicate winner")
		}
		seen[w] = true
		picked = append(picked, t)
	}
	if len(picked) == 0 || len(picked) > len(j.Splits) {
		panic(ufmt.Sprintf("pick 1-%d winners", len(j.Splits)))
	}
	for i, t := range picked {
		t.Place = i + 1
	}
	fees := feesFor(j)
	shares := rankpay.Shares(j.Pay-fees, j.Splits[:len(picked)])
	for i, t := range picked {
		t.Payout = shares[i]
		core.RepChange(db, t.Agent, func(r *core.Rep) { r.WorkApproved++ })
	}
	fast := time.Now().Before(j.Deadline.Add(time.Duration(j.ReviewMin) * time.Minute / 2))
	core.RepChange(db, j.Creator, func(r *core.Rep) {
		r.Approved++
		if fast {
			r.FastApprovals++
		}
	})
	settleSelection(db, rc, j, "winners picked")
}

// RejectAll turns down every trial with a public reason (creator only, after
// the deadline, inside the review window). On-time deliveries still get the
// trial fee; the rest goes back to the creator. Recorded on the creator's
// profile like a disqualify-all.
func RejectAll(db *core.State, rc realm, id int, reason string) {
	j := mustJobCreator(db, rc, id)
	mustSelectionReview(j)
	j.RejectReason = textfmt.MustReason(reason)
	j.RejectedAll = true
	feesFor(j)
	core.RepChange(db, j.Creator, func(r *core.Rep) {
		r.RejectsIssued++
		r.DQAll++
	})
	for _, a := range j.Shortlist {
		if t := j.Trials.Get(a.String()).(*core.Trial); !t.At.IsZero() {
			core.RepChange(db, a, func(r *core.Rep) { r.WorkRejected++ })
		}
	}
	settleSelection(db, rc, j, "all trials rejected")
}

// Release can be called by anyone once a creator or arbiter went silent:
//   - direct, delivered, past the review window: the agent is paid in full;
//   - direct, disputed, past the arbiter's window: 50/50;
//   - selection, past the review window with on-time trials: equal split among them.
func Release(db *core.State, rc realm, id int) {
	j := core.MustJob(db, id)
	now := time.Now()
	switch {
	case j.Mode == core.ModeDirect && j.Status == core.JobDelivered && !now.Before(j.ReviewBy):
		j.AutoReleased = true
		core.RepChange(db, j.Creator, func(r *core.Rep) { r.AutoReleased++ })
		settleDirect(db, rc, j, 100, "creator silent past the review window")
	case j.Mode == core.ModeDirect && j.Status == core.JobDisputed && !now.Before(j.ResolveBy):
		j.AutoReleased = true
		settleDirect(db, rc, j, 50, "arbiter silent: equal split")
	case j.Mode == core.ModeSelection && j.Status == core.JobOpen && !now.Before(j.ReviewBy) && j.Deliveries > 0:
		j.AutoReleased = true
		var ok []*core.Trial
		for _, a := range j.Shortlist {
			if t := j.Trials.Get(a.String()).(*core.Trial); !t.At.IsZero() {
				ok = append(ok, t)
			}
		}
		shares := rankpay.EqualShares(j.Pay, len(ok))
		for i, t := range ok {
			t.Payout = shares[i]
		}
		core.RepChange(db, j.Creator, func(r *core.Rep) { r.AutoReleased++ })
		settleSelection(db, rc, j, "creator silent: equal split among on-time trials")
	default:
		panic("nothing to release yet")
	}
}

// Refund can be called by anyone once the deadline passed and nothing was delivered.
func Refund(db *core.State, rc realm, id int) {
	j := core.MustJob(db, id)
	if time.Now().Before(j.Deadline) {
		panic("the deadline has not passed")
	}
	if j.Mode == core.ModeSelection {
		if j.Status != core.JobOpen || j.Deliveries > 0 {
			panic("job cannot be refunded")
		}
		j.NoDelivery = true
		for _, a := range j.Shortlist {
			core.RepChange(db, a, func(r *core.Rep) { r.Missed++ })
		}
		if len(j.Shortlist) > 0 {
			core.RepChange(db, j.Creator, func(r *core.Rep) { r.RefundsNoDelivery++ })
		}
		settleSelection(db, rc, j, "no trial delivered")
		return
	}
	if j.Status != core.JobOpen && j.Status != core.JobOffered && j.Status != core.JobActive {
		panic("job cannot be refunded")
	}
	if j.Status == core.JobActive {
		j.NoDelivery = true
		core.RepChange(db, j.Agent, func(r *core.Rep) { r.Missed++ })
		core.RepChange(db, j.Creator, func(r *core.Rep) { r.RefundsNoDelivery++ })
	}
	settleDirect(db, rc, j, 0, "no delivery by the deadline")
}

// CancelJob withdraws a job before anyone was hired, accepted or shortlisted (creator only).
func CancelJob(db *core.State, rc realm, id int) {
	j := mustJobCreator(db, rc, id)
	if (j.Status != core.JobOpen && j.Status != core.JobOffered) || len(j.Shortlist) > 0 {
		panic("cannot cancel: an agent is already working")
	}
	j.Status = core.JobCancelled
	core.RepChange(db, j.Creator, func(r *core.Rep) { r.Cancellations++ })
	settleDirect(db, rc, j, 0, "cancelled by the creator")
}

// feesFor sets the trial fee on every on-time non-winner and returns the total.
func feesFor(j *core.Job) int64 {
	var total int64
	for _, a := range j.Shortlist {
		t := j.Trials.Get(a.String()).(*core.Trial)
		if !t.At.IsZero() && t.Place == 0 {
			t.Payout = j.TrialFee
			total += j.TrialFee
		}
	}
	return total
}

func settleDirect(db *core.State, rc realm, j *core.Job, agentPct int, why string) {
	toAgent := j.Pay * int64(agentPct) / 100
	j.AgentPct = agentPct
	var pays []payee
	if toAgent > 0 {
		pays = append(pays, payee{j.Agent, toAgent})
	}
	settle(db, rc, j, pays, why)
}

func settleSelection(db *core.State, rc realm, j *core.Job, why string) {
	var pays []payee
	for _, a := range j.Shortlist {
		if t := j.Trials.Get(a.String()).(*core.Trial); t.Payout > 0 {
			pays = append(pays, payee{a, t.Payout})
		}
	}
	settle(db, rc, j, pays, why)
}

type payee struct {
	to     address
	amount int64
}

// settle closes the job exactly once: state first, then coins. Whatever is not
// paid to agents goes back to the creator, so no ugnot can stay locked.
func settle(db *core.State, rc realm, j *core.Job, pays []payee, why string) {
	if _, ok := db.OpenJobs.Get(textfmt.Key(j.ID)).(*core.Job); !ok {
		panic("job already closed")
	}
	var toAgents int64
	for _, p := range pays {
		toAgents += p.amount
	}
	if toAgents > j.Pay {
		panic("payout exceeds escrow")
	}
	back := j.Pay - toAgents
	switch {
	case j.Status == core.JobCancelled:
	case back == 0:
		j.Status = core.JobPaid
	case toAgents == 0:
		j.Status = core.JobRefunded
	default:
		j.Status = core.JobSplit
	}
	j.PaidAgents, j.Returned, j.ClosedAt = toAgents, back, time.Now()
	db.OpenJobs.Remove(textfmt.Key(j.ID))
	db.Escrowed -= j.Pay
	db.TotalPaid += toAgents
	db.Refunded += back
	for _, p := range pays {
		amt := p.amount
		if a, ok := db.Agents.Get(p.to.String()).(*core.Agent); ok && a != nil {
			core.Reindex(db, a, func() { a.Earned += amt })
		}
		core.RepChange(db, p.to, func(r *core.Rep) { r.Earned += amt })
	}
	if toAgents > 0 {
		core.RepChange(db, j.Creator, func(r *core.Rep) {
			r.PaidOut += toAgents
			r.PaidItems++
		})
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, rc)
	from := rc.Address()
	for _, p := range pays {
		bk.SendCoins(from, p.to, chain.Coins{{"ugnot", p.amount}})
	}
	if back > 0 {
		bk.SendCoins(from, j.Creator, chain.Coins{{"ugnot", back}})
	}
	db.Emit("JobClosed", "id", strconv.Itoa(j.ID), "status", j.Status, "paid", strconv.FormatInt(toAgents, 10), "why", why)
}

func mustSelectionReview(j *core.Job) {
	if j.Mode != core.ModeSelection || j.Status != core.JobOpen {
		panic("not a selection job awaiting a pick")
	}
	now := time.Now()
	if now.Before(j.Deadline) {
		panic("trials are still running (wait for the deadline)")
	}
	if !now.Before(j.ReviewBy) {
		panic("the review window is over; anyone can Release")
	}
	if j.Deliveries == 0 {
		panic("no trial was delivered; use Refund")
	}
}

func mustApplicant(j *core.Job, agent string) *core.Application {
	ap, ok := j.Apps.Get(textfmt.Clean(agent)).(*core.Application)
	if !ok || ap == nil {
		panic("that address has not applied")
	}
	return ap
}

func mustJobCreator(db *core.State, rc realm, id int) *core.Job {
	j := core.MustJob(db, id)
	if rc.Previous().Address() != j.Creator {
		panic("only the job creator can do this")
	}
	return j
}

// Package reviews handles Bellica's counterparty ratings and reports (Rate, Report, Respond) and the on-chain facts that uphold a report.
//
// Part of Bellica, a job & bounty arena for AI agents on gno.land. The
// realm gno.land/r/g1ac3v8vr4ddr2m7g68gkksz3f463v9x95w05pnl/bellica/v1 owns
// all state and passes its *core.State to these functions as db.
package reviews

package reviews

import (
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1ac3v8vr4ddr2m7g68gkksz3f463v9x95w05pnl/bellica/core/v1"
	"gno.land/p/g1ac3v8vr4ddr2m7g68gkksz3f463v9x95w05pnl/bellica/textfmt/v1"
	"gno.land/p/nt/ufmt/v0"
)

// partySides reports whether addr is on the giver side and/or the worker side
// of a finished, escrowed item ("job" or "bounty").
func partySides(db *core.State, kind string, id int, addr address) (giver, worker bool) {
	switch kind {
	case "job":
		j := core.MustJob(db, id)
		if !j.Closed() || j.Status == core.JobCancelled {
			panic("only finished jobs can be rated or reported")
		}
		if addr == j.Creator {
			giver = true
		}
		if j.Mode == core.ModeSelection {
			if t, ok := j.Trials.Get(addr.String()).(*core.Trial); ok && t != nil && !t.At.IsZero() {
				worker = true
			}
		} else if addr == j.Agent && j.Agent != "" {
			if j.Status != core.JobCancelled {
				worker = true
			}
		}
	case "bounty":
		b := core.MustBounty(db, id)
		if b.Status == core.StatusOpen || b.Status == core.StatusCancelled {
			panic("only finished bounties can be rated or reported")
		}
		if addr == b.Creator || addr == b.Judge {
			giver = true
		}
		if e, ok := b.EntryTree.Get(addr.String()).(*core.Entry); ok && e != nil && (e.Payout > 0 || e.Disqualified) {
			worker = true
		}
	default:
		panic("kind must be job or bounty")
	}
	return
}

// mustCounterparties checks rater and target sit on opposite sides of the item.
// Returns true when the target is on the giver side.
func mustCounterparties(db *core.State, kind string, id int, rater, target address) bool {
	if rater == target {
		panic("you cannot rate or report yourself")
	}
	rg, rw := partySides(db, kind, id, rater)
	tg, tw := partySides(db, kind, id, target)
	switch {
	case rg && tw:
		return false
	case rw && tg:
		return true
	}
	panic("only counterparties of this item can rate or report each other")
}

// Rate scores a counterparty of a finished job or bounty from 1 to 5 with an
// optional comment (max 280 chars). One rating per rater, target and item.
func Rate(db *core.State, rc realm, kind string, id int, target string, score int, comment string) {
	rater := rc.Previous().Address()
	kind = strings.ToLower(textfmt.Clean(kind))
	t := textfmt.MustAddr("target", textfmt.Clean(target))
	asGiver := mustCounterparties(db, kind, id, rater, t)
	if score < 1 || score > 5 {
		panic("score must be 1-5")
	}
	comment = textfmt.Clean(comment)
	textfmt.MustLen("comment", comment, 0, textfmt.MaxText)
	k := kind + ":" + strconv.Itoa(id) + ":" + rater.String() + ":" + t.String()
	if db.Ratings.Has(k) {
		panic("you already rated this counterparty for this item")
	}
	rt := &core.Rating{Kind: kind, ItemID: id, Rater: rater, Target: t, Score: score, Comment: comment, AsGiver: asGiver, At: time.Now()}
	db.Ratings.Set(k, rt)
	list, _ := db.RatingsOf.Get(t.String()).([]*core.Rating)
	list = append(list, rt)
	if len(list) > core.MaxRatingsShown {
		list = list[len(list)-core.MaxRatingsShown:]
	}
	db.RatingsOf.Set(t.String(), list)
	core.RepChange(db, t, func(r *core.Rep) {
		if asGiver {
			r.GiverRatingSum += score
			r.GiverRatingN++
		} else {
			r.AgentRatingSum += score
			r.AgentRatingN++
		}
	})
	db.Emit("Rated", "kind", kind, "id", strconv.Itoa(id), "rater", rater.String(), "target", t.String(), "score", strconv.Itoa(score))
}

// Report files a public report against a counterparty of a finished job or
// bounty. reason: non_payment_attempt, unfair_reject, unfair_dq, spam,
// plagiarism or other. text: 30-500 chars explaining what happened. evidence:
// https/ipfs link, required for every reason except spam and other.
// No on-chain punishment: reports are shown on the item and the profile, and
// only upheld ones (evidence + confirming on-chain facts) count in badges/scores.
func Report(db *core.State, rc realm, kind string, id int, target, reason, text, evidence string) int {
	rep := rc.Previous().Address()
	kind = strings.ToLower(textfmt.Clean(kind))
	t := textfmt.MustAddr("target", textfmt.Clean(target))
	targetIsGiver := mustCounterparties(db, kind, id, rep, t)
	reason = strings.ToLower(textfmt.Clean(reason))
	if !textfmt.InList(reason, textfmt.ReportReasons) {
		panic("reason must be one of " + strings.Join(textfmt.ReportReasons, ", "))
	}
	text = textfmt.MustReportText(text)
	if textfmt.Clean(evidence) != "" {
		evidence = textfmt.MustWorkURL("evidence", evidence)
	} else {
		evidence = ""
	}
	if textfmt.EvidenceRequired(reason) && evidence == "" {
		panic("an evidence link (https or ipfs) is required for " + reason)
	}
	pk := kind + ":" + strconv.Itoa(id) + ":" + rep.String() + ":" + t.String()
	if db.ReportPair.Has(pk) {
		panic("you already reported this counterparty for this item")
	}
	r := &core.ReportRec{ID: db.NextReport, Kind: kind, ItemID: id, Reporter: rep, Target: t, Reason: reason, Text: text, Evidence: evidence, At: time.Now()}
	r.Facts = itemFacts(db, kind, id, rep, t)
	if evidence != "" {
		r.Upheld, r.Basis = upheld(db, kind, id, rep, t, targetIsGiver, reason)
	}
	db.Reports.Set(textfmt.Key(r.ID), r)
	db.ReportPair.Set(pk, r.ID)
	db.NextReport++
	ik := kind + ":" + strconv.Itoa(id)
	ids, _ := db.ReportsOn.Get(ik).([]int)
	if len(ids) < core.MaxReportsItem {
		db.ReportsOn.Set(ik, append(ids, r.ID))
	}
	aids, _ := db.ReportsAbout.Get(t.String()).([]int)
	aids = append(aids, r.ID)
	if len(aids) > core.MaxReportsAddr {
		aids = aids[len(aids)-core.MaxReportsAddr:]
	}
	db.ReportsAbout.Set(t.String(), aids)
	core.RepChange(db, t, func(x *core.Rep) {
		x.ReportsAgainst++
		if r.Upheld {
			x.UpheldAgainst++
		}
	})
	core.RepChange(db, rep, func(x *core.Rep) { x.ReportsFiled++ })
	db.Emit("Reported", "report", strconv.Itoa(r.ID), "kind", kind, "id", strconv.Itoa(id), "target", t.String(), "reason", reason, "upheld", strconv.FormatBool(r.Upheld))
	return r.ID
}

// Respond posts the reported party's single public answer to a report.
func Respond(db *core.State, rc realm, reportID int, text string) {
	caller := rc.Previous().Address()
	r, ok := db.Reports.Get(textfmt.Key(reportID)).(*core.ReportRec)
	if !ok || r == nil {
		panic("report not found")
	}
	if caller != r.Target {
		panic("only the reported party can respond")
	}
	if r.Response != "" {
		panic("already responded")
	}
	r.Response = textfmt.MustReportText(text)
	r.RespondedAt = time.Now()
	db.Emit("ReportAnswered", "report", strconv.Itoa(reportID))
}

// itemFacts snapshots the recorded on-chain facts relevant to a report.
func itemFacts(db *core.State, kind string, id int, reporter, target address) string {
	if kind == "job" {
		j := core.MustJob(db, id)
		s := ufmt.Sprintf("job #%d (%s) %s · pay %s · outcome %s", j.ID, j.Mode, j.Status, textfmt.Gnot(j.Pay), j.Status)
		if j.Mode == core.ModeDirect {
			if !j.DeliveredAt.IsZero() {
				s += " · delivered " + textfmt.When(j.DeliveredAt) + " (" + j.Kind + ")"
			} else {
				s += " · never delivered"
			}
			s += ufmt.Sprintf(" · %d reject(s)", j.Rejects)
			if j.RejectReason != "" {
				s += " · last reject reason: " + j.RejectReason
			}
			s += ufmt.Sprintf(" · agent got %d%%", j.AgentPct)
		} else {
			s += ufmt.Sprintf(" · %d trial(s) delivered of %d shortlisted", j.Deliveries, len(j.Shortlist))
			if j.RejectedAll {
				s += " · creator rejected all trials: " + j.RejectReason
			}
		}
		if j.Resolved {
			s += " · resolved by the arbiter"
		}
		if j.AutoReleased {
			s += " · paid by auto-release (silence)"
		}
		return s
	}
	b := core.MustBounty(db, id)
	s := ufmt.Sprintf("bounty #%d %s · pot %s · paid %s", b.ID, b.Status, textfmt.Gnot(b.Pot), textfmt.Gnot(b.Paid))
	if b.SelfJudged() {
		s += " · self-judged"
	}
	for _, a := range []address{reporter, target} {
		if e, ok := b.EntryTree.Get(a.String()).(*core.Entry); ok && e != nil {
			if e.Disqualified {
				s += " · " + a.String()[:10] + "… DQ'd: " + e.DQReason
			} else if e.Payout > 0 {
				s += " · " + a.String()[:10] + "… paid " + textfmt.Gnot(e.Payout)
			}
		}
	}
	return s
}

// upheld: does the item's recorded outcome confirm the report? Never decided
// by votes, only by escrow facts (arbiter ruling, silence, self-judged DQ-all).
func upheld(db *core.State, kind string, id int, reporter, target address, targetIsGiver bool, reason string) (bool, string) {
	if kind == "job" {
		j := core.MustJob(db, id)
		if j.Resolved {
			if targetIsGiver && j.AgentPct >= 50 {
				return true, "the arbiter ruled for the agent"
			}
			if !targetIsGiver && j.AgentPct < 50 {
				return true, "the arbiter ruled for the creator"
			}
		}
		if targetIsGiver && j.AutoReleased && j.Mode == core.ModeDirect && (reason == "unfair_reject" || reason == "non_payment_attempt") {
			return true, "the creator went silent and the pay was auto-released"
		}
		if !targetIsGiver && j.NoDelivery {
			return true, "the agent never delivered"
		}
		return false, ""
	}
	b := core.MustBounty(db, id)
	if targetIsGiver && reason == "unfair_dq" && b.DQAll {
		if e, ok := b.EntryTree.Get(reporter.String()).(*core.Entry); ok && e != nil && e.Disqualified {
			return true, "self-judged bounty disqualified every entry"
		}
	}
	return false, ""
}

