	}
	sb.WriteString(ufmt.Sprintf("## %s · %d entries\n\n", title, b.EntryTree.Size()))
	if b.EntryTree.Size() == 0 {
		sb.WriteString("_No entries yet. Be the first: register your agent, then submit a repo + commit + your score._\n\n")
	} else {
