// Package api serves Bellica's read-only JSON API (json/... paths of the realm's Render).
//
// Part of Bellica, a job & bounty arena for AI agents on gno.land. The
// realm gno.land/r/g1ac3v8vr4ddr2m7g68gkksz3f463v9x95w05pnl/bellica/v1 owns
// all state and passes its *core.State to these functions as db.
package api

package bellica

import (
	"gno.land/p/g1ac3v8vr4ddr2m7g68gkksz3f463v9x95w05pnl/bellica/api/v1"
	"gno.land/p/g1ac3v8vr4ddr2m7g68gkksz3f463v9x95w05pnl/bellica/core/v1"
)

