func TestLeaderboard(cur realm, t *testing.T) {
	resetMeta()

	// low crafts 1 ingot (renown 1), mid 2 (renown 2), high 3 (renown 3).
	low := craftAs(cross(cur), t, "forger-lb-low", 1)
	mid := craftAs(cross(cur), t, "forger-lb-mid", 2)
	high := craftAs(cross(cur), t, "forger-lb-high", 3)

	uassert.Equal(t, 3, len(topTen))
	uassert.Equal(t, high, topTen[0].addr)
	uassert.Equal(t, int64(3), topTen[0].score)
	uassert.Equal(t, mid, topTen[1].addr)
	uassert.Equal(t, int64(2), topTen[1].score)
	uassert.Equal(t, low, topTen[2].addr)
	uassert.Equal(t, int64(1), topTen[2].score)

	// Twelve more single-ingot crafters join; the board caps at ten.
	for i := 0; i < 12; i++ {
		craftAs(cross(cur), t, "forger-lb-fill"+strconv.Itoa(i), 1)
	}
	uassert.Equal(t, leaderboardSize, len(topTen))

	// Every adjacent pair honours score-desc, address-asc ordering.
	for i := 1; i < len(topTen); i++ {
		ordered := topTenBetter(topTen[i-1], topTen[i]) ||
			(topTen[i-1].score == topTen[i].score &&
				topTen[i-1].addr.String() < topTen[i].addr.String())
		uassert.True(t, ordered)
	}
	// The three-ingot leader is still on top.
	uassert.Equal(t, int64(3), topTen[0].score)

	// The lowest board entry crafts two more ingots and climbs to renown 3.
	last := topTen[len(topTen)-1].addr
	urequire.NoError(t, ledger.Mint(last, "ore", 4))
	testing.SetRealm(testing.NewUserRealm(last))
	Craft(cross(cur), "ingot")
	Craft(cross(cur), "ingot")

	found := -1
	for i, e := range topTen {
		if e.addr == last {
			found = i
		}
	}
	uassert.True(t, found >= 0)
	uassert.True(t, topTen[found].score >= int64(3))
}

func TestRenderPages(t *testing.T) {
	player := testutils.TestAddress("forger-render")
	urequire.NoError(t, ledger.MintBatch(player,
		[]grc1155.TokenID{"wood", "ore"}, []int64{4, 2}))

	// Home: header, play links, catalog, recipes, leaderboard, inv hint.
	out := Render("")
	uassert.True(t, strings.Contains(out, "# The Tavern Forge"))
	uassert.True(t, strings.Contains(out, "$help&func=Gather"))
	uassert.True(t, strings.Contains(out, "$help&func=Craft&recipe=sword"))
	uassert.True(t, strings.Contains(out, "$help&func=Craft&recipe=ingot"))
	uassert.True(t, strings.Contains(out, "$help&func=Craft&recipe=shield"))
	uassert.True(t, strings.Contains(out, "Oak Wood"))
	uassert.True(t, strings.Contains(out, "Iron Ore"))
	uassert.True(t, strings.Contains(out, "Iron Ingot"))
	uassert.True(t, strings.Contains(out, "Iron Sword"))
	uassert.True(t, strings.Contains(out, "Oak Shield"))
	uassert.True(t, strings.Contains(out, "Hall of renown"))
	uassert.True(t, strings.Contains(out, ":inv/"))

	// Item page: display name, supply, how it is made and used.
	out = Render("item/sword")
	uassert.True(t, strings.Contains(out, "# Iron Sword"))
	uassert.True(t, strings.Contains(out, "Supply:"))
	uassert.True(t, strings.Contains(out, "Obtained by:"))
	uassert.True(t, strings.Contains(out, "1 x Iron Ingot + 2 x Oak Wood"))
	uassert.True(t, strings.Contains(out, "$help&func=Craft&recipe=sword"))

	// A gathered material points back at Gather.
	out = Render("item/wood")
	uassert.True(t, strings.Contains(out, "# Oak Wood"))
	uassert.True(t, strings.Contains(out, "$help&func=Gather"))

	// Unknown and empty ids get the same fixed message, never echoed.
	out = Render("item/dragonfire")
	uassert.True(t, strings.Contains(out, "no such item"))
	uassert.False(t, strings.Contains(out, "dragonfire"))
	out = Render("item/")
	uassert.True(t, strings.Contains(out, "no such item"))

	// Inventory lists display names and quantities, plus renown.
	out = Render("inv/" + player.String())
	uassert.True(t, strings.Contains(out, "Oak Wood"))
	uassert.True(t, strings.Contains(out, "Iron Ore"))
	uassert.True(t, strings.Contains(out, "| 4 |"))
	uassert.True(t, strings.Contains(out, "| 2 |"))
	uassert.True(t, strings.Contains(out, "Renown:"))

	// An empty satchel gets a friendly message and a Gather link.
	empty := testutils.TestAddress("forger-nobody")
	out = Render("inv/" + empty.String())
	uassert.True(t, strings.Contains(out, "satchel is empty"))
	uassert.True(t, strings.Contains(out, "$help&func=Gather"))

	// Invalid segments are refused with fixed messages, never echoed.
	out = Render("inv/not-an-address!!")
	uassert.True(t, strings.Contains(out, "Not an address"))
	uassert.False(t, strings.Contains(out, "not-an-address"))
	out = Render("inv/" + strings.ToUpper(player.String()))
	uassert.True(t, strings.Contains(out, "Not an address"))

	// An unknown page shape gets the fixed fallback.
	out = Render("a/b/c")
	uassert.True(t, strings.Contains(out, "nothing on that shelf"))
}

package forge

import (
	"strconv"
	"strings"

	"gno.land/p/g1j9c3manpp89kdyhjjqqyugty70kjy5w4sw9y0m/grc1155/v0"
)

// realmPath is this realm's gnoweb path; action links hang $help&func=...
// off it and pages hang :sub/path segments.
const realmPath = "/r/g1j9c3manpp89kdyhjjqqyugty70kjy5w4sw9y0m/forge/v0"

// Render serves the forge's gnoweb pages. "" is home; "item/<id>" is a ware
// page for known ids only; "inv/<addr>" is a player's kit. Every other path —
// and every invalid segment — gets a fixed message; nothing user-controlled
// is ever echoed into the markdown.
func Render(path string) string {
	parts := strings.Split(path, "/")
	switch {
	case path == "":
		return renderHome()
	case len(parts) == 2 && parts[0] == "item":
		return renderItem(parts[1])
	case len(parts) == 2 && parts[0] == "inv":
		return renderInventory(parts[1])
	default:
		return "## The forge goes quiet\n\n" +
			"There is nothing on that shelf. Head back to the " +
			"[forge](" + realmPath + ").\n"
	}
}

func renderHome() string {
	var b strings.Builder

	b.WriteString("# The Tavern Forge\n\n")
	b.WriteString("Behind the taproom, where the regulars swap stories over ale, ")
	b.WriteString("a working forge never goes cold. Gather wood and ore out back, ")
	b.WriteString("smelt and shape them at the anvil, and hang your name among the ")
	b.WriteString("tavern's most renowned crafters.\n\n")

	b.WriteString("## How to play\n\n")
	b.WriteString("- [**Gather**](" + realmPath + "$help&func=Gather) — " +
		"2 Oak Wood + 1 Iron Ore per call, once every " +
		strconv.Itoa(gatherCooldown) + " blocks.\n")
	for _, r := range recipes {
		b.WriteString("- [**Craft " + r.id + "**](" + realmPath +
			"$help&func=Craft&recipe=" + r.id + ") — " + recipeText(r) + ".\n")
	}
	b.WriteString("- [**Transfer**](" + realmPath + "$help&func=Transfer) — ")
	b.WriteString("send loot to another player (args: to, id, amount).\n")
	b.WriteString("- [**Batch transfer**](" + realmPath +
		"$help&func=BatchTransfer) — several stacks at once ")
	b.WriteString("(args: to, ids, amounts — comma-separated).\n")
	b.WriteString("- [**Set approval**](" + realmPath +
		"$help&func=SetApprovalForAll) — let an operator move your items ")
	b.WriteString("(args: operator, approved).\n\n")

	b.WriteString("## Wares on the anvil\n\n")
	b.WriteString("| Item | Obtained by | Supply | Used for |\n")
	b.WriteString("|---|---|---:|---|\n")
	for _, it := range items {
		b.WriteString("| [" + it.name + "](" + realmPath + ":item/" + it.id +
			") (`" + it.id + "`) | " + sourceText(it.id) + " | " +
			supplyText(it.id) + " | " + it.useIn + " |\n")
	}
	b.WriteString("\n")

	b.WriteString("## Hall of renown\n\n")
	if len(topTen) == 0 {
		b.WriteString("No one has lifted a hammer yet — the forge is cold. ")
		b.WriteString("Be the first name on the board.\n")
	} else {
		b.WriteString("| # | Player | Renown |\n")
		b.WriteString("|---:|---|---:|\n")
		for i, e := range topTen {
			b.WriteString("| " + strconv.Itoa(i+1) + " | [" +
				shortAddr(e.addr) + "](" + realmPath + ":inv/" +
				e.addr.String() + ") | " +
				strconv.FormatInt(e.score, 10) + " |\n")
		}
	}
	b.WriteString("\n")

	b.WriteString("## Your kit\n\n")
	b.WriteString("Every crafter's pockets are on their own page — open yours at ")
	b.WriteString("`" + realmPath + ":inv/<your g1 address>`.\n")

	return b.String()
}

func renderItem(id string) string {
	it := findItem(id)
	if it == nil {
		return "## The forge knows no such item\n\n" +
			"This page is not on the anvil. See the " +
			"[forge catalog](" + realmPath + ").\n"
	}

	var b strings.Builder
	b.WriteString("# " + it.name + "\n\n")
	b.WriteString(it.desc + "\n\n")
	b.WriteString("- **Item id:** `" + it.id + "`\n")
	b.WriteString("- **Supply:** " + supplyText(it.id) + "\n")
	b.WriteString("- **Obtained by:** " + sourceText(it.id) + "\n")
	b.WriteString("- **Used for:** " + it.useIn + "\n\n")

	if r := recipeFor(it.id); r != nil {
		b.WriteString("[Craft " + it.name + "](" + realmPath +
			"$help&func=Craft&recipe=" + r.id + ")\n")
	} else {
		b.WriteString("[Gather more](" + realmPath + "$help&func=Gather)\n")
	}

	return b.String()
}

func renderInventory(addrStr string) string {
	addr := address(addrStr)
	// IsValid plus the lowercase-canonical form: an uppercase bech32 spelling
	// is a different ledger key, so it can never hold forge items.
	if !addr.IsValid() || addrStr != strings.ToLower(addrStr) {
		return "## Not an address\n\n" +
			"`inv/` expects a player address like `g1...`. " +
			"See the [forge](" + realmPath + ").\n"
	}

	var tids []grc1155.TokenID
	var bals []int64
	after := grc1155.TokenID("")
	for {
		pageIDs, pageBals := token.HoldingsAfter(addr, after, 50)
		if len(pageIDs) == 0 {
			break
		}
		tids = append(tids, pageIDs...)
		bals = append(bals, pageBals...)
		if len(pageIDs) < 50 {
			break
		}
		after = pageIDs[len(pageIDs)-1]
	}

	var b strings.Builder
	b.WriteString("## " + shortAddr(addr) + "'s kit\n\n")

	if len(tids) == 0 {
		b.WriteString("The satchel is empty — nothing gathered, nothing crafted. ")
		b.WriteString("[Head out back to gather](" + realmPath +
			"$help&func=Gather); the forge provides the materials.\n")
		return b.String()
	}

	b.WriteString("| Item | Quantity |\n")
	b.WriteString("|---|---:|\n")
	for i, tid := range tids {
		b.WriteString("| [" + itemName(tid.String()) + "](" + realmPath +
			":item/" + tid.String() + ") | " +
			strconv.FormatInt(bals[i], 10) + " |\n")
	}
	b.WriteString("\n")
	b.WriteString("**Renown:** " +
		strconv.FormatInt(renownScore(addr), 10) + "\n")

	return b.String()
}

// sourceText describes how an item is obtained: its recipe when one exists,
// otherwise gathering.
func sourceText(id string) string {
	if r := recipeFor(id); r != nil {
		return "Craft — " + recipeText(*r)
	}
	return "Gathered behind the tavern."
}

func supplyText(id string) string {
	return strconv.FormatInt(token.TotalSupply(grc1155.TokenID(id)), 10)
}

// shortAddr abbreviates a bech32 address for table display; the full address
// stays in the link target.
func shortAddr(addr address) string {
	s := addr.String()
	if len(s) > 14 {
		return s[:14] + "…"
	}
	return s
}

package verification

import "strconv"

// RealmProof verification realm. Stores an auditable, append-only registry of
// evidence hashes. The submitted hash must be calculated off-chain, and the
// realm does not claim that the referenced external assertion is true.
var submissionCount int
var submitted = make(map[string]bool)
var submissions = make(map[int]string)

// RegisterEvidence rejects empty or repeated evidence digests.
func RegisterEvidence(hash string) int {
    if len(hash) != 64 {
        panic("evidence hash must contain 64 hexadecimal characters")
    }
    for _, ch := range hash {
        if !((ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f')) {
            panic("evidence hash must be lowercase hexadecimal")
        }
    }
    if submitted[hash] {
        panic("evidence hash already registered")
    }
    submissionCount++
    submitted[hash] = true
    submissions[submissionCount] = hash
    return submissionCount
}

func Count() int {
    return submissionCount
}

func HasEvidence(hash string) bool {
    return submitted[hash]
}

func Render(path string) string {
    return "# RealmProof Evidence Registry\n\n" +
        "Registered evidence hashes: " + strconv.Itoa(submissionCount) + "\n\n" +
        "This registry records evidence commitments but does not validate external test results."
}

package verification

import "testing"

func TestRegistry(t *testing.T) {
    if Count() != 0 {
        t.Fatal("expected empty registry")
    }
    hash := "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
    index := RegisterEvidence(hash)
    if index != 1 || Count() != 1 || !HasEvidence(hash) {
        t.Fatal("failed to register evidence")
    }
}

package registry

import (
    "chain/runtime"
    "strconv"
    "strings"
)

type Scenario struct {
    ID int
    Author address
    Title string
    TargetRealm string
    Payload string
    VerifyCount int
}

var scenarios []Scenario

func RegisterScenario(cur realm, title string, targetRealm string, payload string) int {
    id := len(scenarios) + 1
    scenarios = append(scenarios, Scenario{id, runtime.PreviousRealm().Address(), title, targetRealm, payload, 0})
    return id
}

func VerifyScenario(cur realm, id int) int {
    if id < 1 || id > len(scenarios) { panic("scenario not found") }
    scenarios[id-1].VerifyCount++
    return scenarios[id-1].VerifyCount
}

func GetScenario(id int) string {
    if id < 1 || id > len(scenarios) { return "" }
    s := scenarios[id-1]
    return strconv.Itoa(s.ID) + " | " + s.Author.String() + " | " + s.Title + " | " + s.TargetRealm + " | " + s.Payload + " | " + strconv.Itoa(s.VerifyCount)
}

func GetScenarioCount() int { return len(scenarios) }

func cell(s string) string {
    return strings.ReplaceAll(strings.ReplaceAll(s, "\n", " "), "|", "\\|")
}

func Render(path string) string {
    path = strings.Trim(path, "/")
    if strings.HasPrefix(path, "scenario/") {
        id, err := strconv.Atoi(strings.TrimPrefix(path, "scenario/"))
        if err != nil || id < 1 || id > len(scenarios) { return "# Scenario not found" }
        s := scenarios[id-1]
        return "# " + cell(s.Title) + "\n\n- **ID:** " + strconv.Itoa(s.ID) + "\n- **Target realm:** `" + cell(s.TargetRealm) + "`\n- **Verifications:** " + strconv.Itoa(s.VerifyCount) + "\n- **Author:** `" + s.Author.String() + "`\n\n[Open in RealmFlow](https://gnoflow-flny.vercel.app/?s=" + s.Payload + ")\n\n[Back to catalog](../)"
    }
    if path != "" { return "# Page not found" }
    var b strings.Builder
    b.WriteString("# RealmFlow Registry\n\nShared realm scenarios.\n\n| ID | Title | Target Realm | Verifications | Author | Open in RealmFlow |\n| --- | --- | --- | --- | --- | --- |\n")
    for _, s := range scenarios {
        id := strconv.Itoa(s.ID)
        b.WriteString("| [" + id + "](scenario/" + id + ") | " + cell(s.Title) + " | " + cell(s.TargetRealm) + " | " + strconv.Itoa(s.VerifyCount) + " | " + s.Author.String() + " | [Open](https://gnoflow-flny.vercel.app/?s=" + s.Payload + ") |\n")
    }
    return b.String()
}

package registry

import (
    "strings"
    "testing"
)

func TestScenarioLifecycle(cur realm, t *testing.T) {
    testing.SetOriginCaller("g1jg8mtutu9khhfwc4nxmuhcpftf0pajdhfvsqf5")
    before := GetScenarioCount()
    id := RegisterScenario(cross(cur), "First scenario", "gno.land/r/demo/boards", "payload")
    if id != before+1 || GetScenarioCount() != before+1 { t.Fatal("scenario was not registered") }
    if !strings.Contains(GetScenario(id), "First scenario | gno.land/r/demo/boards | payload | 0") { t.Fatal("scenario was not returned") }
    if VerifyScenario(cross(cur), id) != 1 || VerifyScenario(cross(cur), id) != 2 { t.Fatal("verification count was not incremented") }
    if !strings.HasSuffix(GetScenario(id), " | 2") { t.Fatal("verification count was not stored") }
    if GetScenario(0) != "" { t.Fatal("invalid ID should return empty string") }
    if !strings.Contains(Render(""), "First scenario") || !strings.Contains(Render(""), "| 2 |") { t.Fatal("catalog missing scenario or count") }
    if !strings.Contains(Render("scenario/1"), "First scenario") || !strings.Contains(Render("scenario/1"), "?s=payload") { t.Fatal("detail missing scenario or link") }
}

